import React, { useState, useEffect, useMemo } from 'react';
import { Task, SortOption } from './types';
import CircularProgress from './components/CircularProgress';
import TaskCard from './components/TaskCard';
import { Plus, LayoutGrid, Search, Target, Filter } from 'lucide-react';

const INITIAL_TASKS: Task[] = [
  {
    id: '1',
    title: 'Design Progress App',
    description: 'Create high-fidelity mockups.',
    percentage: 65,
    isCompleted: false,
    subtasks: [
      { id: 's1', title: 'User research', isCompleted: true },
      { id: 's2', title: 'Wireframes', isCompleted: true },
      { id: 's3', title: 'Visual identity', isCompleted: false },
    ],
    createdAt: Date.now() - 86400000 * 2,
  },
  {
    id: '2',
    title: 'Framer Motion Pro',
    description: 'Build production-ready animations.',
    percentage: 33,
    isCompleted: false,
    subtasks: [
      { id: 's4', title: 'Transitions', isCompleted: true },
    ],
    createdAt: Date.now() - 86400000,
  }
];

const App: React.FC = () => {
  const [tasks, setTasks] = useState<Task[]>(() => {
    const saved = localStorage.getItem('ascend_tasks_v2');
    return saved ? JSON.parse(saved) : INITIAL_TASKS;
  });
  const [search, setSearch] = useState('');
  const [sortBy, setSortBy] = useState<SortOption>('newest');
  const [showAddModal, setShowAddModal] = useState(false);
  const [newTask, setNewTask] = useState({ title: '', description: '' });

  useEffect(() => {
    localStorage.setItem('ascend_tasks_v2', JSON.stringify(tasks));
  }, [tasks]);

  const overallProgress = useMemo(() => {
    if (tasks.length === 0) return 0;
    const total = tasks.reduce((acc, task) => acc + task.percentage, 0);
    return total / tasks.length;
  }, [tasks]);

  const filteredAndSortedTasks = useMemo(() => {
    let result = tasks.filter(t => 
      t.title.toLowerCase().includes(search.toLowerCase())
    );

    result.sort((a, b) => {
      if (sortBy === 'newest') return b.createdAt - a.createdAt;
      if (sortBy === 'oldest') return a.createdAt - b.createdAt;
      if (sortBy === 'progress') return b.percentage - a.percentage;
      return 0;
    });

    return result;
  }, [tasks, search, sortBy]);

  const addTask = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newTask.title.trim()) return;
    const task: Task = {
      id: crypto.randomUUID(),
      title: newTask.title,
      description: newTask.description,
      percentage: 0,
      isCompleted: false,
      subtasks: [],
      createdAt: Date.now(),
    };
    setTasks([task, ...tasks]);
    setNewTask({ title: '', description: '' });
    setShowAddModal(false);
  };

  const updateTask = (updatedTask: Task) => {
    setTasks(tasks.map(t => t.id === updatedTask.id ? updatedTask : t));
  };

  const deleteTask = (id: string) => {
    setTasks(tasks.filter(t => t.id !== id));
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-30 px-6 py-3">
        <div className="max-w-7xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white shadow-md">
              <Target size={18} />
            </div>
            <h1 className="text-lg font-bold tracking-tight">Ascend</h1>
          </div>

          <div className="flex items-center gap-3">
            <div className="relative group">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
              <input
                type="text"
                placeholder="Search..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="pl-9 pr-3 py-1.5 bg-slate-100 border-none rounded-lg text-xs focus:ring-2 focus:ring-indigo-500 outline-none w-48 transition-all"
              />
            </div>
            <button 
              onClick={() => setShowAddModal(true)}
              className="bg-indigo-600 text-white px-4 py-1.5 rounded-lg font-bold text-xs hover:bg-indigo-700 transition-all flex items-center gap-1"
            >
              <Plus size={14} /> Add
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-6 py-6">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">

          {/* Sidebar / Consolidated Stats */}
          <aside className="lg:col-span-3 space-y-4">
            <div className="bg-white p-6 rounded-2xl border border-slate-200 flex flex-col items-center">
              <h2 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-4">Total Progress</h2>
              <CircularProgress percentage={overallProgress} />
              <div className="mt-6 space-y-2 w-full">
                <div className="flex justify-between items-center px-3 py-2 bg-slate-50 rounded-xl">
                  <span className="text-[10px] font-bold text-slate-400 uppercase">Tasks</span>
                  <span className="text-sm font-bold text-slate-700">{tasks.length}</span>
                </div>
                <div className="flex justify-between items-center px-3 py-2 bg-emerald-50 rounded-xl">
                  <span className="text-[10px] font-bold text-emerald-600 uppercase">Done</span>
                  <span className="text-sm font-bold text-emerald-700">
                    {tasks.filter(t => t.isCompleted).length}
                  </span>
                </div>
              </div>
            </div>
          </aside>

          {/* Tasks Main View - Higher Density Grid */}
          <div className="lg:col-span-9">
            <div className="flex items-center justify-between mb-4 px-1">
              <div className="flex items-center gap-2">
                <LayoutGrid size={16} className="text-indigo-600" />
                <h2 className="text-sm font-bold text-slate-800 uppercase tracking-wider">Pipeline</h2>
              </div>

              <div className="flex items-center gap-2">
                <Filter size={14} className="text-slate-400" />
                <select 
                  value={sortBy}
                  onChange={(e) => setSortBy(e.target.value as SortOption)}
                  className="bg-transparent text-[11px] font-bold text-slate-500 uppercase tracking-tight outline-none cursor-pointer hover:text-indigo-600"
                >
                  <option value="newest">Newest</option>
                  <option value="oldest">Oldest</option>
                  <option value="progress">Progress</option>
                </select>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-3">
              {filteredAndSortedTasks.length > 0 ? (
                filteredAndSortedTasks.map(task => (
                  <TaskCard 
                    key={task.id} 
                    task={task} 
                    onUpdate={updateTask}
                    onDelete={deleteTask}
                  />
                ))
              ) : (
                <div className="col-span-full py-12 flex flex-col items-center justify-center text-slate-300 bg-white rounded-2xl border-2 border-dashed border-slate-100">
                  <Target size={24} className="mb-2" />
                  <p className="text-xs font-bold uppercase tracking-widest">No Active Tasks</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </main>

      {/* Add Task Modal */}
      {showAddModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/20 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-sm rounded-2xl shadow-xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-6">
              <h2 className="text-lg font-bold text-slate-800 mb-4">Add Task</h2>
              <form onSubmit={addTask} className="space-y-4">
                <input
                  autoFocus required type="text"
                  value={newTask.title}
                  onChange={(e) => setNewTask({ ...newTask, title: e.target.value })}
                  className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-indigo-500"
                  placeholder="Task title..."
                />
                <div className="flex gap-2 pt-2">
                  <button type="button" onClick={() => setShowAddModal(false)} className="flex-1 py-2 text-xs font-bold text-slate-500 uppercase">Cancel</button>
                  <button type="submit" className="flex-1 py-2 bg-indigo-600 text-white rounded-xl text-xs font-bold uppercase shadow-lg shadow-indigo-100">Create</button>
                </div>
              </form>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

