      ...task,
      isCompleted: nextStatus,
      percentage: nextStatus ? 100 : (task.percentage === 100 ? 0 : task.percentage)
    });
  };

  const addSubtask = (title: string) => {
    if (!title.trim()) return;
    const newSub: Subtask = {
      id: crypto.randomUUID(),
      title: title.trim(),
      isCompleted: false
    };
    const updatedSubtasks = [...task.subtasks, newSub];
    const completedCount = updatedSubtasks.filter(s => s.isCompleted).length;
    const autoPercent = Math.round((completedCount / updatedSubtasks.length) * 100);

    onUpdate({ ...task, subtasks: updatedSubtasks, percentage: autoPercent });
    setNewSubtaskTitle('');
  };

  const handleAiBreakdown = async () => {
    setIsAiLoading(true);
    const suggested = await generateSubtasks(task.title, task.description);
    if (suggested.length > 0) {
      const newSubs: Subtask[] = suggested.map((s: any) => ({
        id: crypto.randomUUID(),
        title: s.title,
        isCompleted: false
      }));
      onUpdate({ ...task, subtasks: [...task.subtasks, ...newSubs] });
      setIsExpanded(true);
    }
    setIsAiLoading(false);
  };

  const toggleSubtask = (subId: string) => {
    const updatedSubtasks = task.subtasks.map(s => 
      s.id === subId ? { ...s, isCompleted: !s.isCompleted } : s
    );
    const completedCount = updatedSubtasks.filter(s => s.isCompleted).length;
    const autoPercent = Math.round((completedCount / updatedSubtasks.length) * 100);
    onUpdate({ ...task, subtasks: updatedSubtasks, percentage: autoPercent, isCompleted: autoPercent === 100 });
  };

  return (
    <div className={`group bg-white rounded-lg border border-slate-200 p-2.5 hover:border-indigo-300 transition-all shadow-sm hover:shadow-md ${task.isCompleted ? 'bg-slate-50/50' : ''}`}>
      <div className="flex items-center gap-2">
        <button 
          onClick={toggleTaskCompletion}
          className={`flex-shrink-0 transition-colors ${task.isCompleted ? 'text-emerald-500' : 'text-slate-300 hover:text-indigo-400'}`}
        >
          <CheckCircle2 size={18} fill={task.isCompleted ? 'currentColor' : 'transparent'} />
        </button>

        <div className="min-w-0 flex-1">
          <h3 className={`text-[13px] font-bold truncate ${task.isCompleted ? 'text-slate-400 line-through' : 'text-slate-800'}`}>
            {task.title}
          </h3>
        </div>

        <div className="flex items-center gap-0.5 opacity-0 group-hover:opacity-100 transition-opacity">
          <button onClick={handleAiBreakdown} disabled={isAiLoading} title="AI Breakdown" className="p-1 text-indigo-500 hover:bg-indigo-50 rounded">
            {isAiLoading ? <Loader2 size={13} className="animate-spin" /> : <Sparkles size={13} />}
          </button>
          <button onClick={() => onDelete(task.id)} title="Delete" className="p-1 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded">
            <Trash2 size={13} />
          </button>
          <button onClick={() => setIsExpanded(!isExpanded)} title="Expand" className="p-1 text-slate-300 hover:bg-slate-100 rounded">
            {isExpanded ? <ChevronUp size={13} /> : <ChevronDown size={13} />}
          </button>
        </div>
      </div>

      {/* Extreme Compact Progress Control */}
      <div className="mt-2 relative group/progress">
        <div className="flex justify-between items-center mb-1">
           <div className="h-1 flex-1 bg-slate-100 rounded-full overflow-hidden mr-2">
             <div 
                className={`h-full transition-all duration-500 ${task.isCompleted ? 'bg-emerald-400' : 'bg-indigo-500'}`}
                style={{ width: `${task.percentage}%` }}
              />
           </div>
           <span className="text-[10px] font-black text-indigo-600 w-6 text-right">{task.percentage}%</span>
        </div>
        <input
          type="range"
          min="0"
          max="100"
          value={task.percentage}
          onChange={handlePercentageChange}
          className="absolute -top-1 left-0 w-[calc(100%-1.75rem)] h-3 opacity-0 cursor-pointer z-10"
        />
      </div>

      {isExpanded && (
        <div className="mt-2 pt-2 border-t border-slate-50 space-y-0.5 animate-in fade-in slide-in-from-top-1 duration-200">
          {task.subtasks.map(sub => (
            <div key={sub.id} className="flex items-center gap-2 py-0.5 group/sub">
              <button onClick={() => toggleSubtask(sub.id)} className="flex-shrink-0">
                {sub.isCompleted ? <CheckCircle2 size={12} className="text-emerald-500" /> : <Circle size={12} className="text-slate-300" />}
              </button>
              <span className={`text-[11px] leading-tight flex-1 truncate ${sub.isCompleted ? 'text-slate-400 line-through' : 'text-slate-600 font-medium'}`}>{sub.title}</span>
            </div>
          ))}
          <div className="flex items-center gap-1 mt-1.5">
            <input
              type="text"
              placeholder="Add item..."
              value={newSubtaskTitle}
              onChange={(e) => setNewSubtaskTitle(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && addSubtask(newSubtaskTitle)}
              className="flex-1 text-[10px] bg-slate-50 px-1.5 py-0.5 rounded border-none focus:ring-1 focus:ring-indigo-300 outline-none placeholder:text-slate-300"
            />
            <button onClick={() => addSubtask(newSubtaskTitle)} className="p-0.5 text-indigo-600 hover:scale-110 transition-transform"><Plus size={12} /></button>
          </div>
        </div>
      )}
    </div>
  );
};

