import React, { useState, useEffect, useRef } from 'react';
import { X, Play, Pause, Timer as TimerIcon, RotateCcw } from 'lucide-react';

interface TimerOverlayProps {
  subtaskTitle: string;
  onClose: () => void;
  onComplete: (elapsedSeconds: number) => void;
  darkMode: boolean;
}

const TimerOverlay: React.FC<TimerOverlayProps> = ({ subtaskTitle, onClose, onComplete, darkMode }) => {
  const [duration, setDuration] = useState<number>(25); // minutes
  const [timeLeft, setTimeLeft] = useState<number>(0);
  const [isActive, setIsActive] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [isStarted, setIsStarted] = useState(false);
  const [elapsed, setElapsed] = useState(0);

  const timerRef = useRef<number | null>(null);

  const startTimer = () => {
    setTimeLeft(duration * 60);
    setIsStarted(true);
    setIsActive(true);
    setIsPaused(false);
  };

  const togglePause = () => {
    setIsPaused(!isPaused);
  };

  const cancelTimer = () => {
    if (timerRef.current) clearInterval(timerRef.current);
    onComplete(elapsed);
    onClose();
  };

  useEffect(() => {
    if (isActive && !isPaused && timeLeft > 0) {
      timerRef.current = window.setInterval(() => {
        setTimeLeft((prev) => prev - 1);
        setElapsed((prev) => prev + 1);
      }, 1000);
    } else {
      if (timerRef.current) clearInterval(timerRef.current);
    }

    if (timeLeft === 0 && isStarted && isActive) {
      setIsActive(false);
      onComplete(elapsed);
      onClose();
    }

    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [isActive, isPaused, timeLeft]);

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  if (!isStarted) {
    return (
      <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-md animate-in fade-in duration-300">
        <div className={`w-full max-w-sm rounded-3xl p-8 shadow-2xl ${darkMode ? 'bg-slate-900 text-white' : 'bg-white text-slate-900'}`}>
          <div className="flex justify-between items-center mb-6">
            <h2 className="text-xl font-black uppercase tracking-widest">Set Focus Timer</h2>
            <button onClick={onClose} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full">
              <X size={20} />
            </button>
          </div>
          <p className="text-xs font-bold text-slate-400 mb-8 uppercase tracking-widest">Target: {subtaskTitle}</p>

          <div className="flex flex-col items-center gap-6">
            <div className="text-6xl font-black tracking-tighter text-indigo-500">
              {duration}m
            </div>
            <input 
              type="range" 
              min="1" 
              max="120" 
              value={duration} 
              onChange={(e) => setDuration(parseInt(e.target.value))}
              className="w-full h-2 bg-slate-200 dark:bg-slate-800 rounded-lg appearance-none cursor-pointer accent-indigo-500"
            />
            <button 
              onClick={startTimer}
              className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 text-white rounded-2xl font-black uppercase tracking-widest shadow-xl shadow-indigo-500/20 transition-all flex items-center justify-center gap-2"
            >
              <Play size={20} fill="currentColor" /> Start Focus
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 z-[100] flex flex-col items-center justify-center bg-indigo-600 text-white animate-in zoom-in-110 duration-500">
      <div className="absolute top-10 left-10 flex items-center gap-3">
        <div className="w-10 h-10 bg-white/20 rounded-xl flex items-center justify-center">
          <TimerIcon size={24} />
        </div>
        <div>
          <p className="text-[10px] font-black uppercase tracking-[0.2em] opacity-60">Currently Focusing On</p>
          <h2 className="text-lg font-bold">{subtaskTitle}</h2>
        </div>
      </div>

      <div className="text-[180px] font-black tracking-tighter leading-none mb-12 drop-shadow-2xl">
        {formatTime(timeLeft)}
      </div>

      <div className="flex items-center gap-6">
        <button 
          onClick={togglePause}
          className="w-20 h-20 bg-white/10 hover:bg-white/20 backdrop-blur-md rounded-full flex items-center justify-center transition-all border border-white/20"
        >
          {isPaused ? <Play size={32} fill="currentColor" /> : <Pause size={32} fill="currentColor" />}
        </button>
        <button 
          onClick={cancelTimer}
          className="w-20 h-20 bg-white text-indigo-600 rounded-full flex items-center justify-center shadow-2xl font-black text-sm uppercase tracking-widest hover:scale-105 active:scale-95 transition-all"
        >
          Cancel
        </button>
      </div>

      <div className="absolute bottom-10 opacity-30 text-[10px] font-black uppercase tracking-[0.5em]">
        Focusing deeply. Stay consistent.
      </div>
    </div>
  );
};

