};

export default App;

export interface Subtask {
  id: string;
  title: string;
  isCompleted: boolean;
  timeSpent?: number; // Seconds spent on this subtask
}

export interface Task {
  id: string;
  title: string;
  description: string;
  percentage: number; // 0-100
  isCompleted: boolean;
  subtasks: Subtask[];
  createdAt: number;
  totalTimeSpent?: number; // Total seconds spent on this task
}

export type SortOption = 'newest' | 'oldest' | 'progress';

import React, { useState, useEffect, useRef } from 'react';
import { X, Play, Pause, Timer as TimerIcon } from 'lucide-react';

interface TimerOverlayProps {
  subtaskTitle: string;
  onClose: () => void;
  onComplete: (elapsedSeconds: number) => void;
  darkMode: boolean;
}

const TimerOverlay: React.FC<TimerOverlayProps> = ({ subtaskTitle, onClose, onComplete, darkMode }) => {
  const [duration, setDuration] = useState<number>(25); // minutes
  const [timeLeft, setTimeLeft] = useState<number>(0);
  const [isActive, setIsActive] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [isStarted, setIsStarted] = useState(false);
  const [elapsed, setElapsed] = useState(0);

  const timerRef = useRef<number | null>(null);

  // Constants for circular ring
  const size = 320;
  const strokeWidth = 8;
  const radius = (size - strokeWidth) / 2;
  const circumference = radius * 2 * Math.PI;

  const startTimer = () => {
    const totalSeconds = duration * 60;
    setTimeLeft(totalSeconds);
    setIsStarted(true);
    setIsActive(true);
    setIsPaused(false);
  };

  const togglePause = () => {
    setIsPaused(!isPaused);
  };

  const finishTimer = () => {
    if (timerRef.current) clearInterval(timerRef.current);
    onComplete(elapsed);
    onClose();
  };

  useEffect(() => {
    if (isActive && !isPaused && timeLeft > 0) {
      timerRef.current = window.setInterval(() => {
        setTimeLeft((prev) => prev - 1);
        setElapsed((prev) => prev + 1);
      }, 1000);
    } else {
      if (timerRef.current) clearInterval(timerRef.current);
    }

    if (timeLeft === 0 && isStarted && isActive) {
      setIsActive(false);
      onComplete(elapsed);
      onClose();
    }

    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [isActive, isPaused, timeLeft]);

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  const progressOffset = isStarted 
    ? circumference - (timeLeft / (duration * 60)) * circumference 
    : circumference;

  if (!isStarted) {
    return (
      <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-md animate-in fade-in duration-300">
        <div className={`w-full max-w-sm rounded-3xl p-8 shadow-2xl ${darkMode ? 'bg-slate-900 text-white' : 'bg-white text-slate-900'}`}>
          <div className="flex justify-between items-center mb-6">
            <h2 className="text-xl font-light uppercase tracking-widest">Set Focus Timer</h2>
            <button onClick={onClose} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full">
              <X size={20} />
            </button>
          </div>
          <p className="text-xs font-medium text-slate-400 mb-8 uppercase tracking-widest">Target: {subtaskTitle}</p>

          <div className="flex flex-col items-center gap-6">
            <div className="text-6xl font-light tracking-tighter text-indigo-500">
              {duration}m
            </div>
            <input 
              type="range" 
              min="1" 
              max="120" 
              value={duration} 
              onChange={(e) => setDuration(parseInt(e.target.value))}
              className="w-full h-1.5 bg-slate-200 dark:bg-slate-800 rounded-lg appearance-none cursor-pointer accent-indigo-500"
            />
            <button 
              onClick={startTimer}
              className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 text-white rounded-2xl font-medium uppercase tracking-widest shadow-xl shadow-indigo-500/20 transition-all flex items-center justify-center gap-2"
            >
              <Play size={18} /> Start Focus
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className={`fixed inset-0 z-[100] flex flex-col items-center justify-center transition-colors duration-700 ${darkMode ? 'bg-slate-950 text-white' : 'bg-indigo-600 text-white'} animate-in zoom-in-110 duration-500`}>
      <div className="absolute top-10 left-10 flex items-center gap-3">
        <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${darkMode ? 'bg-indigo-500/20' : 'bg-white/20'}`}>
          <TimerIcon size={24} />
        </div>
        <div>
          <p className="text-[10px] font-medium uppercase tracking-[0.2em] opacity-60">Focusing On</p>
          <h2 className="text-lg font-light tracking-wide">{subtaskTitle}</h2>
        </div>
      </div>

      <div className="relative flex items-center justify-center mb-12">
        <svg width={size} height={size} className="transform -rotate-90">
          <circle
            cx={size / 2}
            cy={size / 2}
            r={radius}
            stroke="currentColor"
            strokeWidth={strokeWidth}
            fill="transparent"
            className="opacity-10"
          />
          <circle
            cx={size / 2}
            cy={size / 2}
            r={radius}
            stroke={darkMode ? '#6366f1' : '#ffffff'}
            strokeWidth={strokeWidth}
            fill="transparent"
            strokeDasharray={circumference}
            style={{ 
              strokeDashoffset: progressOffset,
              transition: 'stroke-dashoffset 1s linear'
            }}
            strokeLinecap="round"
          />
        </svg>
        <div className="absolute flex flex-col items-center">
          <span className="text-8xl font-light tracking-tighter tabular-nums drop-shadow-sm">
            {formatTime(timeLeft)}
          </span>
        </div>
      </div>

      <div className="flex items-center gap-8">
        <button 
          onClick={togglePause}
          className={`w-16 h-16 rounded-full flex items-center justify-center transition-all border ${
            darkMode ? 'bg-slate-900 border-slate-800 hover:bg-slate-800' : 'bg-white/10 border-white/20 hover:bg-white/20'
          }`}
        >
          {isPaused ? <Play size={28} /> : <Pause size={28} />}
        </button>
        <button 
          onClick={finishTimer}
          className={`px-10 h-16 rounded-full flex items-center justify-center shadow-2xl font-light text-sm uppercase tracking-[0.2em] hover:scale-105 active:scale-95 transition-all ${
            darkMode ? 'bg-indigo-600 text-white' : 'bg-white text-indigo-600'
          }`}
        >
          Done
        </button>
      </div>

      <div className="absolute bottom-10 opacity-30 text-[10px] font-medium uppercase tracking-[0.5em]">
        Focusing deeply. Stay consistent.
      </div>
    </div>
  );
};

export default TimerOverlay;

import React, { useState, useEffect, useMemo } from 'react';
import { Task, SortOption } from './types';
import CircularProgress from './components/CircularProgress';
import TaskCard from './components/TaskCard';
import TimerOverlay from './components/TimerOverlay';
import { Plus, LayoutGrid, Search, Target, Filter, CheckCircle, ListTodo, Sun, Moon } from 'lucide-react';

const INITIAL_TASKS: Task[] = [
  {
    id: '1',
    title: 'Dashboard Design',
    description: 'Personal tracker mockups.',
    percentage: 85,
    isCompleted: false,
    subtasks: [
      { id: 's1', title: 'User research', isCompleted: true, timeSpent: 1200 },
      { id: 's2', title: 'Wireframes', isCompleted: true, timeSpent: 1800 },
      { id: 's3', title: 'Visual identity', isCompleted: false, timeSpent: 600 },
    ],
    createdAt: Date.now() - 86400000 * 2,
    totalTimeSpent: 3600
  },
  {
    id: '2',
    title: 'React Animation',
    description: 'Build interactions.',
    percentage: 50,
    isCompleted: false,
    subtasks: [
      { id: 's4', title: 'Transitions', isCompleted: true, timeSpent: 1000 },
      { id: 's5', title: 'Hover states', isCompleted: false, timeSpent: 800 },
    ],
    createdAt: Date.now() - 86400000,
    totalTimeSpent: 1800
  }
];

const App: React.FC = () => {
  const [tasks, setTasks] = useState<Task[]>(() => {
    const saved = localStorage.getItem('ascend_tasks_timer_v2');
    return saved ? JSON.parse(saved) : INITIAL_TASKS;
  });
  const [darkMode, setDarkMode] = useState(() => {
    const saved = localStorage.getItem('ascend_theme');
    return saved === 'dark';
  });
  const [search, setSearch] = useState('');
  const [sortBy, setSortBy] = useState<SortOption>('newest');
  const [showAddModal, setShowAddModal] = useState(false);
  const [newTask, setNewTask] = useState({ title: '', description: '' });

  // Timer State
  const [activeTimer, setActiveTimer] = useState<{ taskId: string; subtaskTitle: string } | null>(null);

  useEffect(() => {
    localStorage.setItem('ascend_tasks_timer_v2', JSON.stringify(tasks));
  }, [tasks]);

  useEffect(() => {
    localStorage.setItem('ascend_theme', darkMode ? 'dark' : 'light');
    if (darkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [darkMode]);

  const stats = useMemo(() => {
    if (tasks.length === 0) return { overall: 0, total: 0, completed: 0, subtasks: 0, subtasksCompleted: 0 };
    const totalPercentage = tasks.reduce((acc, task) => acc + task.percentage, 0);
    const subtasks = tasks.flatMap(t => t.subtasks);
    return {
      overall: totalPercentage / tasks.length,
      total: tasks.length,
      completed: tasks.filter(t => t.isCompleted).length,
      subtasks: subtasks.length,
      subtasksCompleted: subtasks.filter(s => s.isCompleted).length
    };
  }, [tasks]);

  const filteredAndSortedTasks = useMemo(() => {
    let result = tasks.filter(t => 
      t.title.toLowerCase().includes(search.toLowerCase())
    );

    result.sort((a, b) => {
      if (sortBy === 'newest') return b.createdAt - a.createdAt;
      if (sortBy === 'oldest') return a.createdAt - b.createdAt;
      if (sortBy === 'progress') return b.percentage - a.percentage;
      return 0;
    });

    return result;
  }, [tasks, search, sortBy]);

  const addTask = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newTask.title.trim()) return;
    const task: Task = {
      id: crypto.randomUUID(),
      title: newTask.title,
      description: newTask.description,
      percentage: 0,
      isCompleted: false,
      subtasks: [],
      createdAt: Date.now(),
      totalTimeSpent: 0
    };
    setTasks([task, ...tasks]);
    setNewTask({ title: '', description: '' });
    setShowAddModal(false);
  };

  const updateTask = (updatedTask: Task) => {
    setTasks(tasks.map(t => t.id === updatedTask.id ? updatedTask : t));
  };

  const deleteTask = (id: string) => {
    setTasks(tasks.filter(t => t.id !== id));
  };

  const recordTime = (elapsed: number) => {
    if (!activeTimer) return;
    setTasks(tasks.map(t => {
      if (t.id === activeTimer.taskId) {
        // Update subtask time if found
        const updatedSubtasks = t.subtasks.map(s => {
          if (s.title === activeTimer.subtaskTitle) {
            return { ...s, timeSpent: (s.timeSpent || 0) + elapsed };
          }
          return s;
        });
        return { 
          ...t, 
          subtasks: updatedSubtasks,
          totalTimeSpent: (t.totalTimeSpent || 0) + elapsed 
        };
      }
      return t;
    }));
    setActiveTimer(null);
  };

  return (
    <div className={`min-h-screen transition-colors duration-300 ${darkMode ? 'bg-slate-950 text-slate-100' : 'bg-[#fcfdfe] text-slate-900'} overflow-x-hidden`}>
      <header className={`border-b sticky top-0 z-30 px-6 py-2.5 transition-colors ${darkMode ? 'bg-slate-900/80 border-slate-800' : 'bg-white/80 border-slate-200'} backdrop-blur-md`}>
        <div className="max-w-[1600px] mx-auto flex items-center justify-between">
          <div className="flex items-center gap-2.5">
            <div className="w-7 h-7 bg-indigo-600 rounded-lg flex items-center justify-center text-white shadow-sm">
              <Target size={16} strokeWidth={2.5} />
            </div>
            <h1 className="text-base font-black tracking-tight uppercase">Ascend</h1>
          </div>

          <div className="flex items-center gap-4">
            <div className="relative group hidden sm:block">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={12} />
              <input
                type="text"
                placeholder="Search focus..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className={`pl-8 pr-3 py-1 border-none rounded-lg text-xs font-medium focus:ring-1 focus:ring-indigo-500 outline-none w-40 transition-all ${darkMode ? 'bg-slate-800 text-slate-200' : 'bg-slate-100 text-slate-700'}`}
              />
            </div>

            <button 
              onClick={() => setDarkMode(!darkMode)}
              className={`p-2 rounded-lg transition-colors ${darkMode ? 'bg-slate-800 text-yellow-400 hover:bg-slate-700' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}
              title={darkMode ? "Switch to Light Mode" : "Switch to Dark Mode"}
            >
              {darkMode ? <Sun size={14} /> : <Moon size={14} />}
            </button>

            <button 
              onClick={() => setShowAddModal(true)}
              className="bg-indigo-600 text-white px-3.5 py-1.5 rounded-lg font-bold text-[11px] uppercase tracking-wider hover:bg-indigo-700 transition-all flex items-center gap-1 shadow-indigo-100 dark:shadow-none shadow-lg"
            >
              <Plus size={14} /> New
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-[1600px] mx-auto px-6 py-6">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">

          {/* Dashboard Analytics Bar */}
          <aside className="lg:col-span-3 space-y-4">
