                </div>
              </form>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Task, Subtask } from '../types';
import { 
  CheckCircle2, 
  ChevronDown, 
  ChevronUp, 
  Trash2, 
  Plus, 
  Sparkles, 
  Loader2, 
  Square, 
  CheckSquare,
  Clock
} from 'lucide-react';
import { generateSubtasks } from '../services/geminiService';

interface TaskCardProps {
  task: Task;
  onUpdate: (updatedTask: Task) => void;
  onDelete: (id: string) => void;
  onStartTimer: (taskId: string, subtaskTitle: string) => void;
  darkMode?: boolean;
}

const TaskCard: React.FC<TaskCardProps> = ({ task, onUpdate, onDelete, onStartTimer, darkMode = false }) => {
  // Subtasks are opened by default
  const [isExpanded, setIsExpanded] = useState(true);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [newSubtaskTitle, setNewSubtaskTitle] = useState('');

  const formatElapsedTime = (seconds?: number) => {
    if (!seconds || seconds === 0) return '0m';
    const h = Math.floor(seconds / 3600);
    const m = Math.floor((seconds % 3600) / 60);
    if (h > 0) return `${h}h ${m}m`;
    return `${m}m`;
  };

  const handlePercentageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = parseInt(e.target.value);
    onUpdate({ 
      ...task, 
      percentage: val,
      isCompleted: val === 100
    });
  };

  const toggleTaskCompletion = () => {
    const nextStatus = !task.isCompleted;
    onUpdate({
      ...task,
      isCompleted: nextStatus,
      percentage: nextStatus ? 100 : (task.percentage === 100 ? 0 : task.percentage)
    });
  };

  const addSubtask = (title: string) => {
    if (!title.trim()) return;
    const newSub: Subtask = {
      id: crypto.randomUUID(),
      title: title.trim(),
      isCompleted: false,
      timeSpent: 0
    };
    const updatedSubtasks = [...task.subtasks, newSub];
    const completedCount = updatedSubtasks.filter(s => s.isCompleted).length;
    const autoPercent = Math.round((completedCount / updatedSubtasks.length) * 100);

    onUpdate({ ...task, subtasks: updatedSubtasks, percentage: autoPercent });
    setNewSubtaskTitle('');
  };

  const handleAiBreakdown = async () => {
    setIsAiLoading(true);
    const suggested = await generateSubtasks(task.title, task.description);
    if (suggested.length > 0) {
      const newSubs: Subtask[] = suggested.map((s: any) => ({
        id: crypto.randomUUID(),
        title: s.title,
        isCompleted: false,
        timeSpent: 0
      }));
      onUpdate({ ...task, subtasks: [...task.subtasks, ...newSubs] });
      setIsExpanded(true);
    }
    setIsAiLoading(false);
  };

  const toggleSubtask = (subId: string) => {
    const updatedSubtasks = task.subtasks.map(s => 
      s.id === subId ? { ...s, isCompleted: !s.isCompleted } : s
    );
    const completedCount = updatedSubtasks.filter(s => s.isCompleted).length;
    const autoPercent = Math.round((completedCount / updatedSubtasks.length) * 100);
    onUpdate({ ...task, subtasks: updatedSubtasks, percentage: autoPercent, isCompleted: autoPercent === 100 });
  };

  return (
    <div className={`group rounded-lg border transition-all shadow-sm hover:shadow-md overflow-hidden ${
      darkMode 
        ? `bg-slate-900 border-slate-800 hover:border-indigo-500/50 ${task.isCompleted ? 'bg-slate-800/40 opacity-80' : ''}` 
        : `bg-white border-slate-200 hover:border-indigo-300 ${task.isCompleted ? 'bg-slate-50/50' : ''}`
    }`}>
      {/* Header section */}
      <div className={`flex items-center gap-2 p-2.5 transition-colors ${
        task.isCompleted 
          ? 'bg-slate-100 dark:bg-slate-800/60' 
          : 'bg-indigo-600'
      }`}>
        <button 
          onClick={toggleTaskCompletion}
          className={`flex-shrink-0 transition-all duration-300 ${task.isCompleted ? 'text-emerald-500 scale-110' : 'text-white/60 hover:text-white'}`}
        >
          <CheckCircle2 size={18} fill={task.isCompleted ? 'currentColor' : 'transparent'} />
        </button>

        <div className="min-w-0 flex-1">
          <h3 className={`text-[13px] font-bold truncate transition-colors ${
            task.isCompleted 
              ? 'text-slate-400 dark:text-slate-500 line-through' 
              : 'text-white'
          }`}>
            {task.title}
          </h3>
        </div>

        <div className="flex items-center gap-0.5 opacity-0 group-hover:opacity-100 transition-opacity">
          <button onClick={handleAiBreakdown} disabled={isAiLoading} title="AI Breakdown" className="p-1 text-white/60 hover:text-white hover:bg-white/10 rounded">
            {isAiLoading ? <Loader2 size={13} className="animate-spin" /> : <Sparkles size={13} />}
          </button>
          <button onClick={() => onDelete(task.id)} title="Delete" className="p-1 text-white/60 hover:text-red-300 hover:bg-white/10 rounded">
            <Trash2 size={13} />
          </button>
          <button onClick={() => setIsExpanded(!isExpanded)} title="Expand" className="p-1 text-white/60 hover:text-white hover:bg-white/10 rounded">
            {isExpanded ? <ChevronUp size={13} /> : <ChevronDown size={13} />}
          </button>
        </div>
      </div>

      <div className="p-2.5 pt-2">
        {/* Total analytics line */}
        <div className="flex items-center gap-1.5 mb-2.5 opacity-60">
           <Clock size={10} className="text-indigo-500" />
           <span className="text-[9px] font-black uppercase tracking-widest text-slate-500 dark:text-slate-400">
             Total Effort: {formatElapsedTime(task.totalTimeSpent)}
           </span>
        </div>

        {/* Progress Control */}
        <div className="relative group/progress">
          <div className="flex justify-between items-center mb-1">
             <div className={`h-1 flex-1 rounded-full overflow-hidden mr-2 transition-colors ${darkMode ? 'bg-slate-800' : 'bg-slate-100'}`}>
               <div 
                  className={`h-full transition-all duration-500 ${task.isCompleted ? 'bg-emerald-400' : 'bg-indigo-500'}`}
                  style={{ width: `${task.percentage}%` }}
                />
             </div>
             <span className="text-[10px] font-black text-indigo-500 dark:text-indigo-400 w-6 text-right">{task.percentage}%</span>
          </div>
          <input
            type="range"
            min="0"
            max="100"
            value={task.percentage}
            onChange={handlePercentageChange}
            className="absolute -top-1 left-0 w-[calc(100%-1.75rem)] h-3 opacity-0 cursor-pointer z-10"
          />
        </div>

        {isExpanded && (
          <div className={`mt-3 pt-3 border-t space-y-3 animate-in fade-in slide-in-from-top-1 duration-200 ${darkMode ? 'border-slate-800' : 'border-slate-50'}`}>
            {task.subtasks.map(sub => (
              <div key={sub.id} className="flex flex-col group/sub">
                <div className="flex items-center gap-2 py-0.5">
                  <button 
                    onClick={() => toggleSubtask(sub.id)} 
                    className={`flex-shrink-0 transition-all duration-200 ${sub.isCompleted ? 'text-emerald-500' : 'text-slate-400 dark:text-slate-600 hover:text-indigo-400'}`}
                  >
                    {sub.isCompleted ? (
                      <CheckSquare size={13} fill="currentColor" className={`${darkMode ? 'bg-slate-900' : 'bg-white'} rounded-[2px]`} />
                    ) : (
                      <Square size={13} />
                    )}
                  </button>
                  <span className={`text-[11px] leading-tight flex-1 truncate transition-colors duration-200 ${
                    sub.isCompleted 
                      ? 'text-slate-400 dark:text-slate-600 line-through' 
                      : 'text-slate-600 dark:text-slate-400 font-medium'
                  }`}>
                    {sub.title}
                  </span>
                  <button 
                    onClick={() => onStartTimer(task.id, sub.title)}
                    className="p-1 opacity-0 group-hover/sub:opacity-100 transition-opacity hover:bg-slate-100 dark:hover:bg-slate-800 rounded-md text-indigo-500"
                    title="Focus Timer"
                  >
                    <Clock size={11} />
                  </button>
                </div>
                {sub.timeSpent && sub.timeSpent > 0 && (
                  <div className="pl-5 flex items-center gap-1 opacity-40">
                    <span className="text-[8px] font-bold uppercase tracking-widest text-slate-500 dark:text-slate-400">Logged: {formatElapsedTime(sub.timeSpent)}</span>
                  </div>
                )}
              </div>
            ))}
            <div className="flex items-center gap-1 mt-1">
              <input
                type="text"
                placeholder="Add item..."
                value={newSubtaskTitle}
                onChange={(e) => setNewSubtaskTitle(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && addSubtask(newSubtaskTitle)}
                className={`flex-1 text-[10px] px-1.5 py-0.5 rounded border-none outline-none transition-colors ${
                  darkMode 
                    ? 'bg-slate-800 text-slate-200 focus:ring-1 focus:ring-indigo-500 placeholder:text-slate-600' 
                    : 'bg-slate-50 text-slate-800 focus:ring-1 focus:ring-indigo-300 placeholder:text-slate-300'
                }`}
              />
              <button onClick={() => addSubtask(newSubtaskTitle)} className="p-0.5 text-indigo-500 hover:scale-110 transition-transform">
                <Plus size={12} />
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default TaskCard;

import React, { useState, useEffect, useMemo } from 'react';
import { Task, SortOption } from './types';
import CircularProgress from './components/CircularProgress';
import TaskCard from './components/TaskCard';
import TimerOverlay from './components/TimerOverlay';
import { 
  Plus, 
  LayoutGrid, 
  Search, 
  Target, 
  Filter, 
  CheckCircle, 
  ListTodo, 
  Sun, 
  Moon,
  Clock,
  BarChart3,
  ChevronRight
} from 'lucide-react';

const INITIAL_TASKS: Task[] = [
  {
    id: '1',
    title: 'Dashboard Design',
    description: 'Personal tracker mockups.',
    percentage: 85,
    isCompleted: false,
    subtasks: [
      { id: 's1', title: 'User research', isCompleted: true, timeSpent: 1200 },
      { id: 's2', title: 'Wireframes', isCompleted: true, timeSpent: 1800 },
      { id: 's3', title: 'Visual identity', isCompleted: false, timeSpent: 600 },
    ],
    createdAt: Date.now() - 86400000 * 2,
    totalTimeSpent: 3600
  },
  {
    id: '2',
    title: 'React Animation',
    description: 'Build interactions.',
    percentage: 50,
    isCompleted: false,
    subtasks: [
      { id: 's4', title: 'Transitions', isCompleted: true, timeSpent: 1000 },
      { id: 's5', title: 'Hover states', isCompleted: false, timeSpent: 800 },
    ],
    createdAt: Date.now() - 86400000,
    totalTimeSpent: 1800
  }
];

const App: React.FC = () => {
  const [tasks, setTasks] = useState<Task[]>(() => {
    const saved = localStorage.getItem('ascend_tasks_timer_v2');
    return saved ? JSON.parse(saved) : INITIAL_TASKS;
  });
  const [darkMode, setDarkMode] = useState(() => {
    const saved = localStorage.getItem('ascend_theme');
    return saved === 'dark';
  });
  const [search, setSearch] = useState('');
  const [sortBy, setSortBy] = useState<SortOption>('newest');
  const [showAddModal, setShowAddModal] = useState(false);
  const [newTask, setNewTask] = useState({ title: '', description: '' });

  // Timer State
  const [activeTimer, setActiveTimer] = useState<{ taskId: string; subtaskTitle: string } | null>(null);

  useEffect(() => {
    localStorage.setItem('ascend_tasks_timer_v2', JSON.stringify(tasks));
  }, [tasks]);

  useEffect(() => {
    localStorage.setItem('ascend_theme', darkMode ? 'dark' : 'light');
    if (darkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [darkMode]);

  const formatTimeFull = (seconds: number) => {
    const h = Math.floor(seconds / 3600);
    const m = Math.floor((seconds % 3600) / 60);
    if (h > 0) return `${h}h ${m}m`;
    return `${m}m`;
  };

  const stats = useMemo(() => {
    if (tasks.length === 0) return { overall: 0, total: 0, completed: 0, subtasks: 0, subtasksCompleted: 0, totalTime: 0 };
    const totalPercentage = tasks.reduce((acc, task) => acc + task.percentage, 0);
    const subtasks = tasks.flatMap(t => t.subtasks);
    const totalTime = tasks.reduce((acc, t) => acc + (t.totalTimeSpent || 0), 0);
    return {
      overall: totalPercentage / tasks.length,
      total: tasks.length,
      completed: tasks.filter(t => t.isCompleted).length,
      subtasks: subtasks.length,
      subtasksCompleted: subtasks.filter(s => s.isCompleted).length,
      totalTime
    };
  }, [tasks]);

  const filteredAndSortedTasks = useMemo(() => {
    let result = tasks.filter(t => 
      t.title.toLowerCase().includes(search.toLowerCase())
    );

    result.sort((a, b) => {
      if (sortBy === 'newest') return b.createdAt - a.createdAt;
      if (sortBy === 'oldest') return a.createdAt - b.createdAt;
      if (sortBy === 'progress') return b.percentage - a.percentage;
      return 0;
    });

    return result;
  }, [tasks, search, sortBy]);

  const addTask = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newTask.title.trim()) return;
    const task: Task = {
      id: crypto.randomUUID(),
      title: newTask.title,
      description: newTask.description,
      percentage: 0,
      isCompleted: false,
      subtasks: [],
      createdAt: Date.now(),
      totalTimeSpent: 0
    };
    setTasks([task, ...tasks]);
    setNewTask({ title: '', description: '' });
    setShowAddModal(false);
  };

  const updateTask = (updatedTask: Task) => {
    setTasks(tasks.map(t => t.id === updatedTask.id ? updatedTask : t));
  };

  const deleteTask = (id: string) => {
    setTasks(tasks.filter(t => t.id !== id));
  };

  const recordTime = (elapsed: number) => {
    if (!activeTimer) return;
    setTasks(tasks.map(t => {
      if (t.id === activeTimer.taskId) {
        // Update subtask time if found
        const updatedSubtasks = t.subtasks.map(s => {
          if (s.title === activeTimer.subtaskTitle) {
            return { ...s, timeSpent: (s.timeSpent || 0) + elapsed };
          }
          return s;
        });
        return { 
          ...t, 
          subtasks: updatedSubtasks,
          totalTimeSpent: (t.totalTimeSpent || 0) + elapsed 
        };
      }
      return t;
    }));
    setActiveTimer(null);
  };

  return (
    <div className={`min-h-screen transition-colors duration-300 ${darkMode ? 'bg-slate-950 text-slate-100' : 'bg-[#fcfdfe] text-slate-900'} overflow-x-hidden`}>
      <header className={`border-b sticky top-0 z-30 px-6 py-2.5 transition-colors ${darkMode ? 'bg-slate-900/80 border-slate-800' : 'bg-white/80 border-slate-200'} backdrop-blur-md`}>
        <div className="max-w-[1600px] mx-auto flex items-center justify-between">
          <div className="flex items-center gap-2.5">
            <div className="w-7 h-7 bg-indigo-600 rounded-lg flex items-center justify-center text-white shadow-sm">
              <Target size={16} strokeWidth={2.5} />
            </div>
            <h1 className="text-base font-black tracking-tight uppercase">Ascend</h1>
          </div>

          <div className="flex items-center gap-4">
            <div className="relative group hidden sm:block">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={12} />
              <input
                type="text"
                placeholder="Search focus..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className={`pl-8 pr-3 py-1 border-none rounded-lg text-xs font-medium focus:ring-1 focus:ring-indigo-500 outline-none w-40 transition-all ${darkMode ? 'bg-slate-800 text-slate-200' : 'bg-slate-100 text-slate-700'}`}
              />
            </div>

            <button 
              onClick={() => setDarkMode(!darkMode)}
              className={`p-2 rounded-lg transition-colors ${darkMode ? 'bg-slate-800 text-yellow-400 hover:bg-slate-700' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}
              title={darkMode ? "Switch to Light Mode" : "Switch to Dark Mode"}
            >
              {darkMode ? <Sun size={14} /> : <Moon size={14} />}
            </button>

            <button 
              onClick={() => setShowAddModal(true)}
              className="bg-indigo-600 text-white px-3.5 py-1.5 rounded-lg font-bold text-[11px] uppercase tracking-wider hover:bg-indigo-700 transition-all flex items-center gap-1 shadow-indigo-100 dark:shadow-none shadow-lg"
            >
              <Plus size={14} /> New
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-[1600px] mx-auto px-6 py-6">
