import React, { useState, useEffect, useRef } from 'react';
import { X, Play, Pause, Timer as TimerIcon } from 'lucide-react';

interface TimerOverlayProps {
  subtaskTitle: string;
  onClose: () => void;
  onComplete: (elapsedSeconds: number) => void;
  darkMode: boolean;
}

const MOTIVATIONAL_QUOTES = [
  "Focus on the step, not the mountain.",
  "Consistency is the companion of success.",
  "Your future self will thank you.",
  "One thing at a time.",
  "Deep work, great results.",
  "Progress over perfection.",
  "Quiet the mind and the soul will speak.",
  "The secret of getting ahead is getting started."
];

const TimerOverlay: React.FC<TimerOverlayProps> = ({ subtaskTitle, onClose, onComplete, darkMode }) => {
  const [duration, setDuration] = useState<number>(25); // minutes
  const [timeLeft, setTimeLeft] = useState<number>(0);
  const [isActive, setIsActive] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [isStarted, setIsStarted] = useState(false);
  const [elapsed, setElapsed] = useState(0);
  const [quoteIndex, setQuoteIndex] = useState(0);

  const timerRef = useRef<number | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);

  // Constants for circular ring
  const size = 320;
  const strokeWidth = 8;
  const radius = (size - strokeWidth) / 2;
  const circumference = radius * 2 * Math.PI;

  const playRingSound = () => {
    try {
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      }
      const ctx = audioContextRef.current;
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();

      osc.type = 'sine';
      osc.frequency.setValueAtTime(880, ctx.currentTime); // A5 note
      osc.frequency.exponentialRampToValueAtTime(440, ctx.currentTime + 0.5); // Slide down to A4

      gain.gain.setValueAtTime(0, ctx.currentTime);
      gain.gain.linearRampToValueAtTime(0.2, ctx.currentTime + 0.1);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 1.5);

      osc.connect(gain);
      gain.connect(ctx.destination);

      osc.start();
      osc.stop(ctx.currentTime + 1.5);
    } catch (e) {
      console.warn("Audio feedback failed:", e);
    }
  };

  const startTimer = () => {
    const totalSeconds = duration * 60;
    setTimeLeft(totalSeconds);
    setIsStarted(true);
    setIsActive(true);
    setIsPaused(false);
  };

  const togglePause = () => {
    setIsPaused(!isPaused);
  };

  const finishTimer = () => {
    if (timerRef.current) clearInterval(timerRef.current);
    onComplete(elapsed);
    onClose();
  };

  // Quote cycling effect
  useEffect(() => {
    if (!isStarted) return;
    const interval = setInterval(() => {
      setQuoteIndex((prev) => (prev + 1) % MOTIVATIONAL_QUOTES.length);
    }, 20000); // Change quote every 20 seconds
    return () => clearInterval(interval);
  }, [isStarted]);

  useEffect(() => {
    if (isActive && !isPaused && timeLeft > 0) {
      timerRef.current = window.setInterval(() => {
        setTimeLeft((prev) => prev - 1);
        setElapsed((prev) => prev + 1);
      }, 1000);
    } else {
      if (timerRef.current) clearInterval(timerRef.current);
    }

    if (timeLeft === 0 && isStarted && isActive) {
      setIsActive(false);
      playRingSound();
      // Brief delay before closing automatically if desired, 
      // but let's just trigger complete and let the user click Done to see the status.
    }

    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [isActive, isPaused, timeLeft]);

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  const progressOffset = isStarted 
    ? circumference - (timeLeft / (duration * 60)) * circumference 
    : circumference;

  if (!isStarted) {
    return (
      <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-md animate-in fade-in duration-300">
        <div className={`w-full max-w-sm rounded-3xl p-8 shadow-2xl ${darkMode ? 'bg-slate-900 text-white' : 'bg-white text-slate-900'}`}>
          <div className="flex justify-between items-center mb-6">
            <h2 className="text-xl font-light uppercase tracking-widest">Set Focus Timer</h2>
            <button onClick={onClose} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full">
              <X size={20} />
            </button>
          </div>
          <p className="text-xs font-medium text-slate-400 mb-8 uppercase tracking-widest">Target: {subtaskTitle}</p>

          <div className="flex flex-col items-center gap-6">
            <div className="text-6xl font-light tracking-tighter text-indigo-500">
              {duration}m
            </div>
            <input 
              type="range" 
              min="1" 
              max="120" 
              value={duration} 
              onChange={(e) => setDuration(parseInt(e.target.value))}
              className="w-full h-1.5 bg-slate-200 dark:bg-slate-800 rounded-lg appearance-none cursor-pointer accent-indigo-500"
            />
            <button 
              onClick={startTimer}
              className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 text-white rounded-2xl font-medium uppercase tracking-widest shadow-xl shadow-indigo-500/20 transition-all flex items-center justify-center gap-2"
            >
              <Play size={18} /> Start Focus
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className={`fixed inset-0 z-[100] flex flex-col items-center justify-center transition-colors duration-700 ${darkMode ? 'bg-slate-950 text-white' : 'bg-indigo-600 text-white'} animate-in zoom-in-110 duration-500`}>
      <div className="absolute top-10 left-10 flex items-center gap-3">
        <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${darkMode ? 'bg-indigo-500/20' : 'bg-white/20'}`}>
          <TimerIcon size={24} />
        </div>
        <div>
          <p className="text-[10px] font-medium uppercase tracking-[0.2em] opacity-60">Focusing On</p>
          <h2 className="text-lg font-light tracking-wide">{subtaskTitle}</h2>
        </div>
      </div>

      <div className="relative flex items-center justify-center mb-8">
        <svg width={size} height={size} className="transform -rotate-90">
          <circle
            cx={size / 2}
            cy={size / 2}
            r={radius}
            stroke="currentColor"
            strokeWidth={strokeWidth}
            fill="transparent"
            className="opacity-10"
          />
          <circle
            cx={size / 2}
            cy={size / 2}
            r={radius}
            stroke={darkMode ? '#6366f1' : '#ffffff'}
            strokeWidth={strokeWidth}
            fill="transparent"
            strokeDasharray={circumference}
            style={{ 
              strokeDashoffset: progressOffset,
              transition: 'stroke-dashoffset 1s linear'
            }}
            strokeLinecap="round"
          />
        </svg>
        <div className="absolute flex flex-col items-center">
          <span className={`text-8xl font-light tracking-tighter tabular-nums transition-opacity duration-300 ${timeLeft === 0 ? 'opacity-20' : 'opacity-100'}`}>
            {formatTime(timeLeft)}
          </span>
          {timeLeft === 0 && (
            <span className="absolute text-2xl font-light uppercase tracking-[0.3em] animate-pulse">
              Completed
            </span>
          )}
        </div>
      </div>

      {/* Motivational Quote Display */}
      <div className="h-12 mb-8 flex items-center justify-center px-6">
        <p key={quoteIndex} className="text-sm font-light italic opacity-60 text-center tracking-wide animate-in fade-in slide-in-from-bottom-2 duration-1000">
          "{MOTIVATIONAL_QUOTES[quoteIndex]}"
        </p>
      </div>

      <div className="flex items-center gap-8">
        <button 
          onClick={togglePause}
          className={`w-16 h-16 rounded-full flex items-center justify-center transition-all border ${
            darkMode ? 'bg-slate-900 border-slate-800 hover:bg-slate-800' : 'bg-white/10 border-white/20 hover:bg-white/20'
          }`}
        >
          {isPaused ? <Play size={28} /> : <Pause size={28} />}
        </button>
        <button 
          onClick={finishTimer}
          className={`px-10 h-16 rounded-full flex items-center justify-center shadow-2xl font-light text-sm uppercase tracking-[0.2em] hover:scale-105 active:scale-95 transition-all ${
            darkMode ? 'bg-indigo-600 text-white' : 'bg-white text-indigo-600'
          }`}
        >
          Done
        </button>
      </div>

      <div className="absolute bottom-10 opacity-30 text-[10px] font-medium uppercase tracking-[0.5em]">
        Stay present. Keep ascending.
      </div>
    </div>
  );
};

export default TimerOverlay;

import React, { useState, useEffect } from 'react';
import { Task, Subtask } from '../types';
import { 
  CheckCircle2, 
  ChevronDown, 
  ChevronUp, 
  Trash2, 
  Plus, 
  Sparkles, 
  Loader2, 
  Square, 
  CheckSquare,
  Clock
} from 'lucide-react';
import { generateSubtasks } from '../services/geminiService';

interface TaskCardProps {
  task: Task;
  onUpdate: (updatedTask: Task) => void;
  onDelete: (id: string) => void;
  onStartTimer: (taskId: string, subtaskTitle: string) => void;
  darkMode?: boolean;
}

const TaskCard: React.FC<TaskCardProps> = ({ task, onUpdate, onDelete, onStartTimer, darkMode = false }) => {
  const [isExpanded, setIsExpanded] = useState(true);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [newSubtaskTitle, setNewSubtaskTitle] = useState('');

  // Track recently completed items to trigger animations
  const [lastCompletedId, setLastCompletedId] = useState<string | null>(null);
  const [justFinishedTask, setJustFinishedTask] = useState(false);

  // Trigger task glow when it hits 100%
  useEffect(() => {
    if (task.percentage === 100 && !justFinishedTask) {
      setJustFinishedTask(true);
      const timer = setTimeout(() => setJustFinishedTask(false), 1500);
      return () => clearTimeout(timer);
    }
  }, [task.percentage]);

  const formatElapsedTime = (seconds?: number) => {
    if (!seconds || seconds === 0) return '0m';
    const h = Math.floor(seconds / 3600);
    const m = Math.floor((seconds % 3600) / 60);
    if (h > 0) return `${h}h ${m}m`;
    return `${m}m`;
  };

  const handlePercentageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = parseInt(e.target.value);
    onUpdate({ 
      ...task, 
      percentage: val,
      isCompleted: val === 100
    });
  };

  const toggleTaskCompletion = () => {
    const nextStatus = !task.isCompleted;
    if (nextStatus) {
      setLastCompletedId(task.id);
      setTimeout(() => setLastCompletedId(null), 500);
    }
    onUpdate({
      ...task,
      isCompleted: nextStatus,
      percentage: nextStatus ? 100 : (task.percentage === 100 ? 0 : task.percentage)
    });
  };

  const addSubtask = (title: string) => {
    if (!title.trim()) return;
    const newSub: Subtask = {
      id: crypto.randomUUID(),
      title: title.trim(),
      isCompleted: false,
      timeSpent: 0
    };
    const updatedSubtasks = [...task.subtasks, newSub];
    const completedCount = updatedSubtasks.filter(s => s.isCompleted).length;
    const autoPercent = Math.round((completedCount / updatedSubtasks.length) * 100);

    onUpdate({ ...task, subtasks: updatedSubtasks, percentage: autoPercent });
    setNewSubtaskTitle('');
  };

  const handleAiBreakdown = async () => {
    setIsAiLoading(true);
    const suggested = await generateSubtasks(task.title, task.description);
    if (suggested.length > 0) {
      const newSubs: Subtask[] = suggested.map((s: any) => ({
        id: crypto.randomUUID(),
        title: s.title,
        isCompleted: false,
        timeSpent: 0
      }));
      onUpdate({ ...task, subtasks: [...task.subtasks, ...newSubs] });
      setIsExpanded(true);
    }
    setIsAiLoading(false);
  };

  const toggleSubtask = (subId: string) => {
    const subtask = task.subtasks.find(s => s.id === subId);
    if (subtask && !subtask.isCompleted) {
      setLastCompletedId(subId);
      setTimeout(() => setLastCompletedId(null), 500);
    }

    const updatedSubtasks = task.subtasks.map(s => 
      s.id === subId ? { ...s, isCompleted: !s.isCompleted } : s
    );
    const completedCount = updatedSubtasks.filter(s => s.isCompleted).length;
    const autoPercent = Math.round((completedCount / updatedSubtasks.length) * 100);
    onUpdate({ ...task, subtasks: updatedSubtasks, percentage: autoPercent, isCompleted: autoPercent === 100 });
  };

  return (
    <div className={`group rounded-lg border transition-all duration-300 shadow-sm hover:shadow-md overflow-hidden ${
      justFinishedTask ? 'task-completed-glow' : ''
    } ${
      darkMode 
        ? `bg-slate-900 border-slate-800 hover:border-indigo-500/50 ${task.isCompleted ? 'bg-slate-800/40 opacity-90' : ''}` 
        : `bg-white border-slate-200 hover:border-indigo-300 ${task.isCompleted ? 'bg-slate-50/50' : ''}`
    }`}>
      {/* Header section */}
      <div className={`flex items-center gap-2 p-2.5 transition-colors duration-500 ${
        task.isCompleted 
          ? 'bg-slate-100 dark:bg-slate-800/60' 
          : 'bg-indigo-600'
      }`}>
        <button 
          onClick={toggleTaskCompletion}
          className={`flex-shrink-0 transition-all duration-300 transform ${
            task.isCompleted ? 'text-emerald-500 scale-110' : 'text-white/60 hover:text-white'
          } ${lastCompletedId === task.id ? 'animate-pop' : ''}`}
        >
          <CheckCircle2 size={18} fill={task.isCompleted ? 'currentColor' : 'transparent'} />
        </button>

        <div className="min-w-0 flex-1">
          <h3 className={`text-[13px] font-bold truncate transition-all duration-500 ${
            task.isCompleted 
              ? 'text-slate-400 dark:text-slate-500 opacity-60' 
              : 'text-white'
          } ${task.isCompleted ? 'strikethrough-animate strikethrough-active' : 'strikethrough-animate'}`}>
            {task.title}
          </h3>
        </div>

        <div className="flex items-center gap-0.5 opacity-0 group-hover:opacity-100 transition-opacity">
          <button onClick={handleAiBreakdown} disabled={isAiLoading} title="AI Breakdown" className="p-1 text-white/60 hover:text-white hover:bg-white/10 rounded">
            {isAiLoading ? <Loader2 size={13} className="animate-spin" /> : <Sparkles size={13} />}
          </button>
          <button onClick={() => onDelete(task.id)} title="Delete" className="p-1 text-white/60 hover:text-red-300 hover:bg-white/10 rounded">
            <Trash2 size={13} />
          </button>
          <button onClick={() => setIsExpanded(!isExpanded)} title="Expand" className="p-1 text-white/60 hover:text-white hover:bg-white/10 rounded">
            {isExpanded ? <ChevronUp size={13} /> : <ChevronDown size={13} />}
          </button>
        </div>
      </div>

      <div className="p-2.5 pt-2">
        {/* Total analytics line */}
        <div className="flex items-center gap-1.5 mb-2.5 opacity-60">
           <Clock size={10} className="text-indigo-500" />
           <span className="text-[9px] font-black uppercase tracking-widest text-slate-500 dark:text-slate-400">
             Total Effort: {formatElapsedTime(task.totalTimeSpent)}
           </span>
        </div>

        {/* Progress Control */}
        <div className="relative group/progress">
          <div className="flex justify-between items-center mb-1">
             <div className={`h-1 flex-1 rounded-full overflow-hidden mr-2 transition-colors ${darkMode ? 'bg-slate-800' : 'bg-slate-100'}`}>
               <div 
                  className={`h-full transition-all duration-700 ease-out ${task.isCompleted ? 'bg-emerald-400' : 'bg-indigo-500'}`}
                  style={{ width: `${task.percentage}%` }}
                />
             </div>
             <span className={`text-[10px] font-black w-6 text-right transition-colors duration-500 ${task.isCompleted ? 'text-emerald-500' : 'text-indigo-500 dark:text-indigo-400'}`}>
               {task.percentage}%
             </span>
          </div>
          <input
            type="range"
            min="0"
            max="100"
            value={task.percentage}
            onChange={handlePercentageChange}
            className="absolute -top-1 left-0 w-[calc(100%-1.75rem)] h-3 opacity-0 cursor-pointer z-10"
          />
        </div>

        {isExpanded && (
          <div className={`mt-3 pt-3 border-t space-y-3 animate-in fade-in slide-in-from-top-1 duration-200 ${darkMode ? 'border-slate-800' : 'border-slate-50'}`}>
            {task.subtasks.map(sub => (
              <div key={sub.id} className="flex flex-col group/sub">
                <div className="flex items-center gap-2 py-0.5">
                  <button 
                    onClick={() => toggleSubtask(sub.id)} 
                    className={`flex-shrink-0 transition-all duration-300 transform ${
                      sub.isCompleted ? 'text-emerald-500 scale-110' : 'text-slate-400 dark:text-slate-600 hover:text-indigo-400'
                    } ${lastCompletedId === sub.id ? 'animate-pop' : ''}`}
                  >
                    {sub.isCompleted ? (
                      <CheckSquare size={13} fill="currentColor" className={`${darkMode ? 'bg-slate-900' : 'bg-white'} rounded-[2px]`} />
                    ) : (
                      <Square size={13} />
                    )}
                  </button>
                  <span className={`text-[11px] leading-tight flex-1 truncate transition-all duration-500 ${
                    sub.isCompleted 
                      ? 'text-slate-400 dark:text-slate-600 opacity-60' 
                      : 'text-slate-600 dark:text-slate-400 font-medium'
                  } ${sub.isCompleted ? 'strikethrough-animate strikethrough-active' : 'strikethrough-animate'}`}>
                    {sub.title}
                  </span>
                  <button 
                    onClick={() => onStartTimer(task.id, sub.title)}
                    className="p-1 opacity-0 group-hover/sub:opacity-100 transition-opacity hover:bg-slate-100 dark:hover:bg-slate-800 rounded-md text-indigo-500"
                    title="Focus Timer"
                  >
                    <Clock size={11} />
                  </button>
                </div>
                {sub.timeSpent && sub.timeSpent > 0 && (
                  <div className="pl-5 flex items-center gap-1 opacity-40">
                    <span className="text-[8px] font-bold uppercase tracking-widest text-slate-500 dark:text-slate-400">Logged: {formatElapsedTime(sub.timeSpent)}</span>
                  </div>
                )}
              </div>
            ))}
            <div className="flex items-center gap-1 mt-1">
              <input
                type="text"
                placeholder="Add item..."
                value={newSubtaskTitle}
                onChange={(e) => setNewSubtaskTitle(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && addSubtask(newSubtaskTitle)}
                className={`flex-1 text-[10px] px-1.5 py-0.5 rounded border-none outline-none transition-colors ${
                  darkMode 
                    ? 'bg-slate-800 text-slate-200 focus:ring-1 focus:ring-indigo-500 placeholder:text-slate-600' 
                    : 'bg-slate-50 text-slate-800 focus:ring-1 focus:ring-indigo-300 placeholder:text-slate-300'
                }`}
              />
              <button onClick={() => addSubtask(newSubtaskTitle)} className="p-0.5 text-indigo-500 hover:scale-110 transition-transform">
                <Plus size={12} />
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default TaskCard;

import React, { useState, useEffect } from 'react';
import { Task, Subtask } from '../types';
import { 
  CheckCircle2, 
  ChevronDown, 
  ChevronUp, 
  Trash2, 
  Plus, 
  Sparkles, 
  Loader2, 
  Square, 
  CheckSquare,
  Clock
} from 'lucide-react';
import { generateSubtasks } from '../services/geminiService';

interface TaskCardProps {
  task: Task;
  onUpdate: (updatedTask: Task) => void;
  onDelete: (id: string) => void;
  onStartTimer: (taskId: string, subtaskTitle: string) => void;
  darkMode?: boolean;
}

const TaskCard: React.FC<TaskCardProps> = ({ task, onUpdate, onDelete, onStartTimer, darkMode = false }) => {
  const [isExpanded, setIsExpanded] = useState(true);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [newSubtaskTitle, setNewSubtaskTitle] = useState('');

  const [lastCompletedId, setLastCompletedId] = useState<string | null>(null);
  const [justFinishedTask, setJustFinishedTask] = useState(false);

  useEffect(() => {
    if (task.percentage === 100 && !justFinishedTask) {
      setJustFinishedTask(true);
      const timer = setTimeout(() => setJustFinishedTask(false), 1500);
      return () => clearTimeout(timer);
    }
  }, [task.percentage]);

  const formatElapsedTime = (seconds?: number) => {
    if (!seconds || seconds === 0) return '0m';
    const h = Math.floor(seconds / 3600);
    const m = Math.floor((seconds % 3600) / 60);
    if (h > 0) return `${h}h ${m}m`;
    return `${m}m`;
  };

  const handlePercentageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = parseInt(e.target.value);
    onUpdate({ 
      ...task, 
      percentage: val,
      isCompleted: val === 100
    });
  };

  const toggleTaskCompletion = () => {
    const nextStatus = !task.isCompleted;
    if (nextStatus) {
      setLastCompletedId(task.id);
      setTimeout(() => setLastCompletedId(null), 500);
    }
    onUpdate({
      ...task,
      isCompleted: nextStatus,
      percentage: nextStatus ? 100 : (task.percentage === 100 ? 0 : task.percentage)
    });
  };

  const addSubtask = (title: string) => {
    if (!title.trim()) return;
    const newSub: Subtask = {
      id: crypto.randomUUID(),
      title: title.trim(),
      isCompleted: false,
      timeSpent: 0
    };
    const updatedSubtasks = [...task.subtasks, newSub];
    const completedCount = updatedSubtasks.filter(s => s.isCompleted).length;
    const autoPercent = Math.round((completedCount / updatedSubtasks.length) * 100);

    onUpdate({ ...task, subtasks: updatedSubtasks, percentage: autoPercent });
    setNewSubtaskTitle('');
  };

  const handleAiBreakdown = async () => {
    setIsAiLoading(true);
    const suggested = await generateSubtasks(task.title, task.description);
    if (suggested.length > 0) {
      const newSubs: Subtask[] = suggested.map((s: any) => ({
        id: crypto.randomUUID(),
        title: s.title,
        isCompleted: false,
        timeSpent: 0
      }));
      onUpdate({ ...task, subtasks: [...task.subtasks, ...newSubs] });
      setIsExpanded(true);
    }
    setIsAiLoading(false);
  };

  const toggleSubtask = (subId: string) => {
    const subtask = task.subtasks.find(s => s.id === subId);
    if (subtask && !subtask.isCompleted) {
      setLastCompletedId(subId);
      setTimeout(() => setLastCompletedId(null), 500);
    }

    const updatedSubtasks = task.subtasks.map(s => 
      s.id === subId ? { ...s, isCompleted: !s.isCompleted } : s
    );
    const completedCount = updatedSubtasks.filter(s => s.isCompleted).length;
    const autoPercent = Math.round((completedCount / updatedSubtasks.length) * 100);
    onUpdate({ ...task, subtasks: updatedSubtasks, percentage: autoPercent, isCompleted: autoPercent === 100 });
  };

  return (
    <div className={`group rounded-lg border transition-all duration-300 shadow-sm hover:shadow-md overflow-hidden ${
      justFinishedTask ? 'task-completed-glow' : ''
    } ${
      darkMode 
        ? `bg-slate-900 border-slate-800 hover:border-indigo-500/50 ${task.isCompleted ? 'bg-slate-800/40 opacity-95' : ''}` 
        : `bg-white border-slate-200 hover:border-indigo-300 ${task.isCompleted ? 'bg-slate-50/50' : ''}`
    }`}>
      {/* Header section - FIXED: Improved completed state background */}
      <div className={`flex items-center gap-2 p-2.5 transition-all duration-500 ${
        task.isCompleted 
          ? 'bg-emerald-500/10 dark:bg-emerald-950/40' 
          : 'bg-indigo-600'
      }`}>
        <button 
          onClick={toggleTaskCompletion}
          className={`flex-shrink-0 transition-all duration-300 transform ${
            task.isCompleted ? 'text-emerald-500 scale-110' : 'text-white/60 hover:text-white'
          } ${lastCompletedId === task.id ? 'animate-pop' : ''}`}
        >
          <CheckCircle2 size={18} fill={task.isCompleted ? 'currentColor' : 'transparent'} />
        </button>

        <div className="min-w-0 flex-1">
          <h3 className={`text-[13px] font-bold truncate transition-all duration-500 ${
            task.isCompleted 
              ? 'text-emerald-600 dark:text-emerald-400 opacity-80' 
              : 'text-white'
          } ${task.isCompleted ? 'strikethrough-animate strikethrough-active' : 'strikethrough-animate'}`}>
            {task.title}
          </h3>
        </div>

        <div className="flex items-center gap-0.5 opacity-0 group-hover:opacity-100 transition-opacity">
          {!task.isCompleted && (
            <button onClick={handleAiBreakdown} disabled={isAiLoading} title="AI Breakdown" className="p-1 text-white/60 hover:text-white hover:bg-white/10 rounded">
              {isAiLoading ? <Loader2 size={13} className="animate-spin" /> : <Sparkles size={13} />}
            </button>
          )}
          <button onClick={() => onDelete(task.id)} title="Delete" className={`p-1 transition-colors rounded ${task.isCompleted ? 'text-slate-400 hover:text-red-500 hover:bg-red-500/10' : 'text-white/60 hover:text-red-300 hover:bg-white/10'}`}>
            <Trash2 size={13} />
          </button>
          <button onClick={() => setIsExpanded(!isExpanded)} title="Expand" className={`p-1 transition-colors rounded ${task.isCompleted ? 'text-slate-400 hover:text-slate-600' : 'text-white/60 hover:text-white hover:bg-white/10'}`}>
            {isExpanded ? <ChevronUp size={13} /> : <ChevronDown size={13} />}
          </button>
        </div>
      </div>

      <div className="p-2.5 pt-2">
        <div className="flex items-center gap-1.5 mb-2.5 opacity-60">
           <Clock size={10} className={task.isCompleted ? 'text-emerald-500' : 'text-indigo-500'} />
           <span className="text-[9px] font-black uppercase tracking-widest text-slate-500 dark:text-slate-400">
             Effort: {formatElapsedTime(task.totalTimeSpent)}
           </span>
        </div>

        <div className="relative group/progress">
          <div className="flex justify-between items-center mb-1">
             <div className={`h-1 flex-1 rounded-full overflow-hidden mr-2 transition-colors ${darkMode ? 'bg-slate-800' : 'bg-slate-100'}`}>
               <div 
                  className={`h-full transition-all duration-700 ease-out ${task.isCompleted ? 'bg-emerald-400' : 'bg-indigo-500'}`}
                  style={{ width: `${task.percentage}%` }}
                />
             </div>
             <span className={`text-[10px] font-black w-6 text-right transition-colors duration-500 ${task.isCompleted ? 'text-emerald-500' : 'text-indigo-500 dark:text-indigo-400'}`}>
               {task.percentage}%
             </span>
          </div>
          <input
            type="range"
            min="0"
            max="100"
            value={task.percentage}
            onChange={handlePercentageChange}
            className="absolute -top-1 left-0 w-[calc(100%-1.75rem)] h-3 opacity-0 cursor-pointer z-10"
          />
        </div>

        {isExpanded && (
          <div className={`mt-3 pt-3 border-t space-y-3 animate-in fade-in slide-in-from-top-1 duration-200 ${darkMode ? 'border-slate-800' : 'border-slate-50'}`}>
            {task.subtasks.map(sub => (
              <div key={sub.id} className="flex flex-col group/sub">
                <div className="flex items-center gap-2 py-0.5">
                  <button 
                    onClick={() => toggleSubtask(sub.id)} 
                    className={`flex-shrink-0 transition-all duration-300 transform ${
                      sub.isCompleted ? 'text-emerald-500 scale-110' : 'text-slate-400 dark:text-slate-600 hover:text-indigo-400'
                    } ${lastCompletedId === sub.id ? 'animate-pop' : ''}`}
                  >
                    {sub.isCompleted ? (
                      <CheckSquare size={13} fill="currentColor" className={`${darkMode ? 'bg-slate-900' : 'bg-white'} rounded-[2px]`} />
                    ) : (
                      <Square size={13} />
                    )}
                  </button>
                  <span className={`text-[11px] leading-tight flex-1 truncate transition-all duration-500 ${
                    sub.isCompleted 
                      ? 'text-emerald-600/60 dark:text-emerald-400/40' 
                      : 'text-slate-600 dark:text-slate-400 font-medium'
                  } ${sub.isCompleted ? 'strikethrough-animate strikethrough-active' : 'strikethrough-animate'}`}>
                    {sub.title}
                  </span>
                  {!sub.isCompleted && (
                    <button 
                      onClick={() => onStartTimer(task.id, sub.title)}
                      className="p-1 opacity-0 group-hover/sub:opacity-100 transition-opacity hover:bg-slate-100 dark:hover:bg-slate-800 rounded-md text-indigo-500"
                      title="Focus Timer"
                    >
                      <Clock size={11} />
                    </button>
                  )}
                </div>
                {sub.timeSpent && sub.timeSpent > 0 && (
                  <div className="pl-5 flex items-center gap-1 opacity-40">
                    <span className="text-[8px] font-bold uppercase tracking-widest text-slate-500 dark:text-slate-400">Logged: {formatElapsedTime(sub.timeSpent)}</span>
                  </div>
                )}
              </div>
            ))}
            {!task.isCompleted && (
              <div className="flex items-center gap-1 mt-1">
                <input
                  type="text"
                  placeholder="Add item..."
                  value={newSubtaskTitle}
                  onChange={(e) => setNewSubtaskTitle(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && addSubtask(newSubtaskTitle)}
                  className={`flex-1 text-[10px] px-1.5 py-0.5 rounded border-none outline-none transition-colors ${
                    darkMode 
                      ? 'bg-slate-800 text-slate-200 focus:ring-1 focus:ring-indigo-500 placeholder:text-slate-600' 
                      : 'bg-slate-50 text-slate-800 focus:ring-1 focus:ring-indigo-300 placeholder:text-slate-300'
                  }`}
                />
                <button onClick={() => addSubtask(newSubtaskTitle)} className="p-0.5 text-indigo-500 hover:scale-110 transition-transform">
                  <Plus size={12} />
                </button>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default TaskCard;

export interface Subtask {
  id: string;
  title: string;
  isCompleted: boolean;
  percentage?: number; // 0-100 granular progress
  timeSpent?: number; // Seconds spent on this subtask
}

export interface Task {
  id: string;
  title: string;
  description: string;
  percentage: number; // 0-100
  isCompleted: boolean;
  subtasks: Subtask[];
  createdAt: number;
  totalTimeSpent?: number; // Total seconds spent on this task
}

export type SortOption = 'newest' | 'oldest' | 'progress';

import React, { useState, useEffect, useMemo } from 'react';
import { Task, SortOption } from './types';
import CircularProgress from './components/CircularProgress';
import TaskCard from './components/TaskCard';
import TimerOverlay from './components/TimerOverlay';
import { 
  Plus, 
  LayoutGrid, 
  Search, 
  Target, 
  Filter, 
  CheckCircle, 
  ListTodo, 
  Sun, 
  Moon,
  Clock,
  BarChart3,
  ChevronRight
} from 'lucide-react';

const INITIAL_TASKS: Task[] = [
  {
    id: '1',
    title: 'Dashboard Design',
    description: 'Personal tracker mockups.',
    percentage: 85,
    isCompleted: false,
    subtasks: [
      { id: 's1', title: 'User research', isCompleted: true, percentage: 100, timeSpent: 1200 },
      { id: 's2', title: 'Wireframes', isCompleted: true, percentage: 100, timeSpent: 1800 },
      { id: 's3', title: 'Visual identity', isCompleted: false, percentage: 55, timeSpent: 600 },
    ],
    createdAt: Date.now() - 86400000 * 2,
    totalTimeSpent: 3600
  },
  {
    id: '2',
    title: 'React Animation',
    description: 'Build interactions.',
    percentage: 50,
    isCompleted: false,
    subtasks: [
      { id: 's4', title: 'Transitions', isCompleted: true, percentage: 100, timeSpent: 1000 },
      { id: 's5', title: 'Hover states', isCompleted: false, percentage: 0, timeSpent: 800 },
    ],
    createdAt: Date.now() - 86400000,
    totalTimeSpent: 1800
  }
];

const App: React.FC = () => {
  const [tasks, setTasks] = useState<Task[]>(() => {
    const saved = localStorage.getItem('ascend_tasks_timer_v3');
    return saved ? JSON.parse(saved) : INITIAL_TASKS;
  });
  const [darkMode, setDarkMode] = useState(() => {
    const saved = localStorage.getItem('ascend_theme');
    return saved === null ? true : saved === 'dark';
  });
  const [search, setSearch] = useState('');
  const [sortBy, setSortBy] = useState<SortOption>('newest');
  const [showAddModal, setShowAddModal] = useState(false);
  const [newTask, setNewTask] = useState({ title: '', description: '' });

  const [activeTimer, setActiveTimer] = useState<{ taskId: string; subtaskTitle: string } | null>(null);

  useEffect(() => {
    localStorage.setItem('ascend_tasks_timer_v3', JSON.stringify(tasks));
  }, [tasks]);

  useEffect(() => {
    localStorage.setItem('ascend_theme', darkMode ? 'dark' : 'light');
    if (darkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [darkMode]);

  const formatTimeFull = (seconds: number) => {
    const h = Math.floor(seconds / 3600);
    const m = Math.floor((seconds % 3600) / 60);
    if (h > 0) return `${h}h ${m}m`;
    return `${m}m`;
  };

  const stats = useMemo(() => {
    if (tasks.length === 0) return { overall: 0, total: 0, completed: 0, subtasks: 0, subtasksCompleted: 0, totalTime: 0 };
    const totalPercentage = tasks.reduce((acc, task) => acc + task.percentage, 0);
    const subtasks = tasks.flatMap(t => t.subtasks);
    const totalTime = tasks.reduce((acc, t) => acc + (t.totalTimeSpent || 0), 0);
    return {
      overall: totalPercentage / tasks.length,
      total: tasks.length,
      completed: tasks.filter(t => t.isCompleted).length,
      subtasks: subtasks.length,
      subtasksCompleted: subtasks.filter(s => s.isCompleted).length,
      totalTime
    };
  }, [tasks]);

  const filteredAndSortedTasks = useMemo(() => {
    let result = tasks.filter(t => 
      t.title.toLowerCase().includes(search.toLowerCase())
    );

    result.sort((a, b) => {
      if (sortBy === 'newest') return b.createdAt - a.createdAt;
      if (sortBy === 'oldest') return a.createdAt - b.createdAt;
      if (sortBy === 'progress') return b.percentage - a.percentage;
      return 0;
    });

    return result;
  }, [tasks, search, sortBy]);

  const addTask = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newTask.title.trim()) return;
    const task: Task = {
      id: crypto.randomUUID(),
      title: newTask.title,
      description: newTask.description,
      percentage: 0,
      isCompleted: false,
      subtasks: [],
      createdAt: Date.now(),
      totalTimeSpent: 0
    };
    setTasks([task, ...tasks]);
    setNewTask({ title: '', description: '' });
    setShowAddModal(false);
  };

  const updateTask = (updatedTask: Task) => {
    setTasks(tasks.map(t => t.id === updatedTask.id ? updatedTask : t));
  };

  const deleteTask = (id: string) => {
    setTasks(tasks.filter(t => t.id !== id));
  };

  const recordTime = (elapsed: number) => {
    if (!activeTimer) return;
    setTasks(tasks.map(t => {
      if (t.id === activeTimer.taskId) {
        const updatedSubtasks = t.subtasks.map(s => {
          if (s.title === activeTimer.subtaskTitle) {
            return { ...s, timeSpent: (s.timeSpent || 0) + elapsed };
          }
          return s;
        });
        return { 
          ...t, 
          subtasks: updatedSubtasks,
          totalTimeSpent: (t.totalTimeSpent || 0) + elapsed 
        };
      }
      return t;
    }));
    setActiveTimer(null);
  };

  return (
    <div className={`min-h-screen transition-colors duration-300 ${darkMode ? 'bg-slate-950 text-slate-100' : 'bg-[#fcfdfe] text-slate-900'} overflow-x-hidden`}>
      <header className={`border-b sticky top-0 z-30 px-6 py-2.5 transition-colors ${darkMode ? 'bg-slate-900/80 border-slate-800' : 'bg-white/80 border-slate-200'} backdrop-blur-md`}>
        <div className="max-w-[1600px] mx-auto flex items-center justify-between">
          <div className="flex items-center gap-2.5">
            <div className="w-7 h-7 bg-indigo-600 rounded-lg flex items-center justify-center text-white shadow-sm">
              <Target size={16} strokeWidth={2.5} />
            </div>
            <h1 className="text-base font-black tracking-tight uppercase">Ascend</h1>
          </div>

          <div className="flex items-center gap-4">
            <div className="relative group hidden sm:block">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={12} />
              <input
                type="text"
                placeholder="Search focus..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className={`pl-8 pr-3 py-1 border-none rounded-lg text-xs font-medium focus:ring-1 focus:ring-indigo-500 outline-none w-40 transition-all ${darkMode ? 'bg-slate-800 text-slate-200' : 'bg-slate-100 text-slate-700'}`}
              />
            </div>

            <button 
              onClick={() => setDarkMode(!darkMode)}
              className={`p-2 rounded-lg transition-colors ${darkMode ? 'bg-slate-800 text-yellow-400 hover:bg-slate-700' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}
              title={darkMode ? "Switch to Light Mode" : "Switch to Dark Mode"}
            >
              {darkMode ? <Sun size={14} /> : <Moon size={14} />}
            </button>

            <button 
              onClick={() => setShowAddModal(true)}
              className="bg-indigo-600 text-white px-3.5 py-1.5 rounded-lg font-bold text-[11px] uppercase tracking-wider hover:bg-indigo-700 transition-all flex items-center gap-1 shadow-indigo-100 dark:shadow-none shadow-lg"
            >
              <Plus size={14} /> New
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-[1600px] mx-auto px-6 py-6">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
          <aside className="lg:col-span-3 space-y-4">
            <div className={`p-6 rounded-2xl border shadow-sm flex flex-col items-center transition-colors ${darkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-100'}`}>
              <h2 className={`text-[10px] font-black uppercase tracking-[0.2em] mb-4 ${darkMode ? 'text-slate-500' : 'text-slate-400'}`}>Focus Score</h2>
              <CircularProgress percentage={stats.overall} size={150} strokeWidth={12} darkMode={darkMode} />

              <div className="mt-8 grid grid-cols-1 gap-2 w-full">
                <div className={`flex justify-between items-center p-3 rounded-xl transition-colors ${darkMode ? 'bg-slate-800/50' : 'bg-slate-50'}`}>
                  <div className="flex items-center gap-2">
                    <ListTodo size={14} className={darkMode ? 'text-slate-500' : 'text-slate-400'} />
                    <span className={`text-[10px] font-black uppercase tracking-wider ${darkMode ? 'text-slate-400' : 'text-slate-500'}`}>Active</span>
                  </div>
                  <span className={`text-sm font-black ${darkMode ? 'text-slate-200' : 'text-slate-800'}`}>{stats.total}</span>
                </div>
                <div className={`flex justify-between items-center p-3 rounded-xl transition-colors ${darkMode ? 'bg-emerald-950/30' : 'bg-emerald-50'}`}>
                  <div className="flex items-center gap-2">
                    <CheckCircle size={14} className="text-emerald-500" />
                    <span className={`text-[10px] font-black uppercase tracking-wider ${darkMode ? 'text-emerald-400' : 'text-emerald-600'}`}>Completed</span>
                  </div>
                  <span className={`text-sm font-black ${darkMode ? 'text-emerald-400' : 'text-emerald-800'}`}>{stats.completed}</span>
                </div>
              </div>
            </div>

            <div className={`p-5 rounded-2xl border shadow-sm transition-colors ${darkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-100'}`}>
              <div className="flex items-center justify-between mb-5">
                <div className="flex items-center gap-2">
                  <BarChart3 size={14} className="text-indigo-500" />
                  <h2 className={`text-[10px] font-black uppercase tracking-[0.2em] ${darkMode ? 'text-slate-400' : 'text-slate-600'}`}>Time Analysis</h2>
                </div>
              </div>
              <div className="mb-6">
                <div className="flex items-baseline gap-1.5 mb-1">
                  <span className={`text-3xl font-light tracking-tighter ${darkMode ? 'text-white' : 'text-slate-800'}`}>
                    {formatTimeFull(stats.totalTime)}
                  </span>
                  <span className={`text-[10px] font-black uppercase tracking-widest ${darkMode ? 'text-slate-500' : 'text-slate-400'}`}>Total Focus</span>
                </div>
              </div>
            </div>
          </aside>

          <div className="lg:col-span-9">
            <div className="flex items-center justify-between mb-4 px-1">
              <div className="flex items-center gap-2">
                <LayoutGrid size={14} className="text-indigo-500" />
                <h2 className={`text-[11px] font-black uppercase tracking-[0.15em] ${darkMode ? 'text-slate-400' : 'text-slate-800'}`}>Pipeline</h2>
              </div>
              <div className="flex items-center gap-3">
                <div className={`flex items-center gap-1.5 px-2 py-1 border rounded-md shadow-sm transition-colors ${darkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-100'}`}>
                  <Filter size={11} className="text-slate-500" />
                  <select 
                    value={sortBy}
                    onChange={(e) => setSortBy(e.target.value as SortOption)}
                    className={`bg-transparent text-[10px] font-black uppercase tracking-tighter outline-none cursor-pointer ${darkMode ? 'text-slate-400' : 'text-slate-500'}`}
                  >
                    <option value="newest" className={darkMode ? 'bg-slate-900' : ''}>Newest</option>
                    <option value="oldest" className={darkMode ? 'bg-slate-900' : ''}>Oldest</option>
                    <option value="progress" className={darkMode ? 'bg-slate-900' : ''}>Progress</option>
                  </select>
                </div>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-4 gap-3 items-start">
              {filteredAndSortedTasks.length > 0 ? (
                filteredAndSortedTasks.map(task => (
                  <TaskCard 
                    key={task.id} 
                    task={task} 
                    onUpdate={updateTask}
                    onDelete={deleteTask}
                    onStartTimer={(taskId, subtaskTitle) => setActiveTimer({ taskId, subtaskTitle })}
                    darkMode={darkMode}
                  />
                ))
              ) : (
                <div className={`col-span-full py-20 flex flex-col items-center justify-center rounded-2xl border border-dashed shadow-sm transition-colors ${darkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200'}`}>
                  <Target size={24} strokeWidth={1} className={`mb-3 ${darkMode ? 'text-slate-800' : 'text-slate-200'}`} />
                  <p className={`text-[10px] font-black uppercase tracking-[0.2em] ${darkMode ? 'text-slate-600' : 'text-slate-400'}`}>Pipeline Empty</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </main>

      {activeTimer && (
        <TimerOverlay 
          subtaskTitle={activeTimer.subtaskTitle}
          darkMode={darkMode}
          onClose={() => setActiveTimer(null)}
          onComplete={recordTime}
        />
      )}

      {showAddModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/20 dark:bg-black/40 backdrop-blur-[2px] animate-in fade-in duration-200">
          <div className={`w-full max-w-sm rounded-2xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200 border transition-colors ${darkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-100'}`}>
            <div className="p-6">
              <h2 className={`text-sm font-black uppercase tracking-wider mb-5 ${darkMode ? 'text-slate-200' : 'text-slate-800'}`}>Create Task</h2>
              <form onSubmit={addTask} className="space-y-4">
                <div className="space-y-1">
                  <label className={`text-[10px] font-black uppercase tracking-widest ml-1 ${darkMode ? 'text-slate-500' : 'text-slate-400'}`}>Title</label>
                  <input
                    autoFocus required type="text"
                    value={newTask.title}
                    onChange={(e) => setNewTask({ ...newTask, title: e.target.value })}
                    className={`w-full px-3 py-2 border rounded-xl text-xs font-semibold outline-none focus:ring-1 focus:ring-indigo-500 transition-colors ${darkMode ? 'bg-slate-800 border-slate-700 text-slate-100' : 'bg-slate-50 border-slate-100 text-slate-900'}`}
                    placeholder="Enter goal name..."
                  />
                </div>
                <div className="flex gap-2 pt-3">
                  <button type="button" onClick={() => setShowAddModal(false)} className={`flex-1 py-2 text-[10px] font-black uppercase tracking-widest ${darkMode ? 'text-slate-50 hover:text-slate-400' : 'text-slate-400 hover:text-slate-500'}`}>Cancel</button>
                  <button type="submit" className="flex-1 py-2 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg shadow-indigo-100 dark:shadow-none">Create</button>
                </div>
              </form>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

