                  <select 
                    value={sortBy}
                    onChange={(e) => setSortBy(e.target.value as SortOption)}
                    className={`bg-transparent text-[10px] font-black uppercase tracking-tighter outline-none cursor-pointer ${darkMode ? 'text-slate-400' : 'text-slate-500'}`}
                  >
                    <option value="newest" className={darkMode ? 'bg-slate-900' : ''}>Newest</option>
                    <option value="oldest" className={darkMode ? 'bg-slate-900' : ''}>Oldest</option>
                    <option value="progress" className={darkMode ? 'bg-slate-900' : ''}>Progress</option>
                  </select>
                </div>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-4 gap-3 items-start">
              {filteredAndSortedTasks.length > 0 ? (
                filteredAndSortedTasks.map(task => (
                  <TaskCard 
                    key={task.id} 
                    task={task} 
                    onUpdate={updateTask}
                    onDelete={deleteTask}
                    onStartTimer={(taskId, subtaskTitle) => setActiveTimer({ taskId, subtaskTitle })}
                    darkMode={darkMode}
                  />
                ))
              ) : (
                <div className={`col-span-full py-20 flex flex-col items-center justify-center rounded-2xl border border-dashed shadow-sm transition-colors ${darkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200'}`}>
                  <Target size={24} strokeWidth={1} className={`mb-3 ${darkMode ? 'text-slate-800' : 'text-slate-200'}`} />
                  <p className={`text-[10px] font-black uppercase tracking-[0.2em] ${darkMode ? 'text-slate-600' : 'text-slate-400'}`}>Pipeline Empty</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </main>

      {activeTimer && (
        <TimerOverlay 
          subtaskTitle={activeTimer.subtaskTitle}
          darkMode={darkMode}
          onClose={() => setActiveTimer(null)}
          onComplete={recordTime}
        />
      )}

      {showAddModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/20 dark:bg-black/40 backdrop-blur-[2px] animate-in fade-in duration-200">
          <div className={`w-full max-w-sm rounded-2xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200 border transition-colors ${darkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-100'}`}>
            <div className="p-6">
              <h2 className={`text-sm font-black uppercase tracking-wider mb-5 ${darkMode ? 'text-slate-200' : 'text-slate-800'}`}>Create Task</h2>
              <form onSubmit={addTask} className="space-y-4">
                <div className="space-y-1">
                  <label className={`text-[10px] font-black uppercase tracking-widest ml-1 ${darkMode ? 'text-slate-500' : 'text-slate-400'}`}>Title</label>
                  <input
                    autoFocus required type="text"
                    value={newTask.title}
                    onChange={(e) => setNewTask({ ...newTask, title: e.target.value })}
                    className={`w-full px-3 py-2 border rounded-xl text-xs font-semibold outline-none focus:ring-1 focus:ring-indigo-500 transition-colors ${darkMode ? 'bg-slate-800 border-slate-700 text-slate-100' : 'bg-slate-50 border-slate-100 text-slate-900'}`}
                    placeholder="Enter goal name..."
                  />
                </div>
                <div className="flex gap-2 pt-3">
                  <button type="button" onClick={() => setShowAddModal(false)} className={`flex-1 py-2 text-[10px] font-black uppercase tracking-widest ${darkMode ? 'text-slate-50 hover:text-slate-400' : 'text-slate-400 hover:text-slate-500'}`}>Cancel</button>
                  <button type="submit" className="flex-1 py-2 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg shadow-indigo-100 dark:shadow-none">Create</button>
                </div>
              </form>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Task, Subtask } from '../types';
import { 
  CheckCircle2, 
  ChevronDown, 
  ChevronUp, 
  Trash2, 
  Plus, 
  Square, 
  CheckSquare,
  Clock,
  CircleDashed
} from 'lucide-react';

interface TaskCardProps {
  task: Task;
  onUpdate: (updatedTask: Task) => void;
  onDelete: (id: string) => void;
  onStartTimer: (taskId: string, subtaskTitle: string) => void;
  darkMode?: boolean;
}

const TaskCard: React.FC<TaskCardProps> = ({ task, onUpdate, onDelete, onStartTimer, darkMode = false }) => {
  const [isExpanded, setIsExpanded] = useState(true);
  const [newSubtaskTitle, setNewSubtaskTitle] = useState('');
  const [editingSubtaskProgress, setEditingSubtaskProgress] = useState<string | null>(null);

  const [lastCompletedId, setLastCompletedId] = useState<string | null>(null);
  const [justFinishedTask, setJustFinishedTask] = useState(false);

  useEffect(() => {
    if (task.percentage === 100 && !justFinishedTask) {
      setJustFinishedTask(true);
      const timer = setTimeout(() => setJustFinishedTask(false), 1500);
      return () => clearTimeout(timer);
    }
  }, [task.percentage]);

  const formatElapsedTime = (seconds?: number) => {
    if (!seconds || seconds === 0) return '0m';
    const h = Math.floor(seconds / 3600);
    const m = Math.floor((seconds % 3600) / 60);
    if (h > 0) return `${h}h ${m}m`;
    return `${m}m`;
  };

  const calculateAutoPercentage = (subs: Subtask[]) => {
    if (subs.length === 0) return 0;
    const total = subs.reduce((acc, s) => acc + (s.percentage || (s.isCompleted ? 100 : 0)), 0);
    return Math.round(total / subs.length);
  };

  const handlePercentageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = parseInt(e.target.value);
    onUpdate({ 
      ...task, 
      percentage: val,
      isCompleted: val === 100
    });
  };

  const toggleTaskCompletion = () => {
    const nextStatus = !task.isCompleted;
    if (nextStatus) {
      setLastCompletedId(task.id);
      setTimeout(() => setLastCompletedId(null), 500);
    }

    const updatedSubs = task.subtasks.map(s => ({ ...s, isCompleted: nextStatus, percentage: nextStatus ? 100 : 0 }));

    onUpdate({
      ...task,
      isCompleted: nextStatus,
      percentage: nextStatus ? 100 : 0,
      subtasks: updatedSubs
    });
  };

  const addSubtask = (title: string) => {
    if (!title.trim()) return;
    const newSub: Subtask = {
      id: crypto.randomUUID(),
      title: title.trim(),
      isCompleted: false,
      percentage: 0,
      timeSpent: 0
    };
    const updatedSubtasks = [...task.subtasks, newSub];
    const autoPercent = calculateAutoPercentage(updatedSubtasks);

    onUpdate({ ...task, subtasks: updatedSubtasks, percentage: autoPercent, isCompleted: autoPercent === 100 });
    setNewSubtaskTitle('');
  };

  const toggleSubtask = (subId: string) => {
    const subtask = task.subtasks.find(s => s.id === subId);
    if (!subtask) return;

    const nextCompleted = !subtask.isCompleted;
    if (nextCompleted) {
      setLastCompletedId(subId);
      setTimeout(() => setLastCompletedId(null), 500);
    }

    const updatedSubtasks = task.subtasks.map(s => 
      s.id === subId ? { ...s, isCompleted: nextCompleted, percentage: nextCompleted ? 100 : 0 } : s
    );
    const autoPercent = calculateAutoPercentage(updatedSubtasks);
    onUpdate({ ...task, subtasks: updatedSubtasks, percentage: autoPercent, isCompleted: autoPercent === 100 });
  };

  const updateSubtaskPercentage = (subId: string, value: number) => {
    const updatedSubtasks = task.subtasks.map(s => 
      s.id === subId ? { ...s, percentage: value, isCompleted: value === 100 } : s
    );
    const autoPercent = calculateAutoPercentage(updatedSubtasks);
    onUpdate({ ...task, subtasks: updatedSubtasks, percentage: autoPercent, isCompleted: autoPercent === 100 });
  };

  return (
    <div className={`group rounded-lg border transition-all duration-300 shadow-sm hover:shadow-md overflow-hidden ${
      justFinishedTask ? 'task-completed-glow' : ''
    } ${
      darkMode 
        ? `bg-slate-900 border-slate-800 hover:border-indigo-500/50 ${task.isCompleted ? 'bg-slate-800/40 opacity-95' : ''}` 
        : `bg-white border-slate-200 hover:border-indigo-300 ${task.isCompleted ? 'bg-slate-50/50' : ''}`
    }`}>
      <div className={`flex items-center gap-2 p-2.5 transition-all duration-500 ${
        task.isCompleted 
          ? 'bg-emerald-500/10 dark:bg-emerald-950/40' 
          : 'bg-indigo-600'
      }`}>
        <button 
          onClick={toggleTaskCompletion}
          className={`flex-shrink-0 transition-all duration-300 transform ${
            task.isCompleted ? 'text-emerald-500 scale-110' : 'text-white/60 hover:text-white'
          } ${lastCompletedId === task.id ? 'animate-pop' : ''}`}
        >
          <CheckCircle2 size={18} fill={task.isCompleted ? 'currentColor' : 'transparent'} />
        </button>

        <div className="min-w-0 flex-1">
          <h3 className={`text-[13px] font-bold truncate transition-all duration-500 ${
            task.isCompleted 
              ? 'text-emerald-600 dark:text-emerald-400 opacity-80' 
              : 'text-white'
          } ${task.isCompleted ? 'strikethrough-animate strikethrough-active' : 'strikethrough-animate'}`}>
            {task.title}
          </h3>
        </div>

        <div className="flex items-center gap-0.5 opacity-0 group-hover:opacity-100 transition-opacity">
          <button onClick={() => onDelete(task.id)} title="Delete" className={`p-1 transition-colors rounded ${task.isCompleted ? 'text-slate-400 hover:text-red-500 hover:bg-red-500/10' : 'text-white/60 hover:text-red-300 hover:bg-white/10'}`}>
            <Trash2 size={13} />
          </button>
          <button onClick={() => setIsExpanded(!isExpanded)} title="Expand" className={`p-1 transition-colors rounded ${task.isCompleted ? 'text-slate-400 hover:text-slate-600' : 'text-white/60 hover:text-white hover:bg-white/10'}`}>
            {isExpanded ? <ChevronUp size={13} /> : <ChevronDown size={13} />}
          </button>
        </div>
      </div>

      <div className="p-2.5 pt-2">
        <div className="flex items-center gap-1.5 mb-2.5 opacity-60">
           <Clock size={10} className={task.isCompleted ? 'text-emerald-500' : 'text-indigo-500'} />
           <span className="text-[9px] font-black uppercase tracking-widest text-slate-500 dark:text-slate-400">
             Effort: {formatElapsedTime(task.totalTimeSpent)}
           </span>
        </div>

        <div className="relative group/progress">
          <div className="flex justify-between items-center mb-1">
             <div className={`h-1 flex-1 rounded-full overflow-hidden mr-2 transition-colors ${darkMode ? 'bg-slate-800' : 'bg-slate-100'}`}>
