export type SortOption = 'newest' | 'oldest' | 'progress';

import React from 'react';
import { X, Clock, Calendar } from 'lucide-react';
import { Session } from '../types';

interface AnalysisModalProps {
  sessions: Session[];
  onClose: () => void;
  darkMode: boolean;
}

const AnalysisModal: React.FC<AnalysisModalProps> = ({ sessions, onClose, darkMode }) => {
  const size = 320;
  const center = size / 2;
  const radius = center - 40;

  // Helper to convert timestamp to degrees (00:00 = -90deg or top)
  const timeToAngle = (timestamp: number) => {
    const date = new Date(timestamp);
    const hours = date.getHours();
    const minutes = date.getMinutes();
    const totalMinutes = hours * 60 + minutes;
    // 1440 minutes in a day, 360 degrees. 1 min = 0.25 degrees.
    return (totalMinutes * 0.25) - 90;
  };

  const describeArc = (startAngle: number, endAngle: number) => {
    const start = polarToCartesian(center, center, radius, endAngle);
    const end = polarToCartesian(center, center, radius, startAngle);
    const largeArcFlag = endAngle - startAngle <= 180 ? "0" : "1";
    return [
      "M", start.x, start.y, 
      "A", radius, radius, 0, largeArcFlag, 0, end.x, end.y
    ].join(" ");
  };

  const polarToCartesian = (centerX: number, centerY: number, radius: number, angleInDegrees: number) => {
    const angleInRadians = (angleInDegrees * Math.PI) / 180.0;
    return {
      x: centerX + radius * Math.cos(angleInRadians),
      y: centerY + radius * Math.sin(angleInRadians)
    };
  };

  const formatTime = (ts: number) => {
    return new Date(ts).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false });
  };

  const formatDuration = (ms: number) => {
    const mins = Math.floor(ms / 60000);
    return `${mins}m`;
  };

  // Grouping/Sorting sessions for the list
  const sortedSessions = [...sessions].sort((a, b) => b.startTime - a.startTime);

  return (
    <div className="fixed inset-0 z-[150] flex items-center justify-center p-4 bg-slate-950/60 backdrop-blur-md animate-in fade-in duration-300">
      <div className={`w-full max-w-4xl max-h-[90vh] rounded-3xl overflow-hidden shadow-2xl border flex flex-col md:flex-row transition-colors ${darkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200'}`}>

        {/* Visual Chart Section */}
        <div className={`flex-1 p-8 flex flex-col items-center justify-center border-b md:border-b-0 md:border-r ${darkMode ? 'border-slate-800 bg-slate-900/50' : 'border-slate-100 bg-slate-50/30'}`}>
          <div className="text-center mb-8">
            <h2 className={`text-sm font-black uppercase tracking-widest ${darkMode ? 'text-slate-200' : 'text-slate-800'}`}>24h Daily Focus</h2>
            <p className="text-[10px] text-slate-500 font-bold uppercase tracking-tighter">Activity Distribution</p>
          </div>

          <div className="relative">
            <svg width={size} height={size}>
              {/* Clock Background Circle */}
              <circle 
                cx={center} cy={center} r={radius} 
                fill="transparent" 
                stroke={darkMode ? "#1e293b" : "#e2e8f0"} 
                strokeWidth="24" 
              />

              {/* Hour Markers */}
              {[...Array(24)].map((_, i) => {
                const angle = (i * 15) - 90;
                const p1 = polarToCartesian(center, center, radius + 15, angle);
                const p2 = polarToCartesian(center, center, radius + 22, angle);
                return (
                  <line 
                    key={i} x1={p1.x} y1={p1.y} x2={p2.x} y2={p2.y} 
                    stroke={i % 6 === 0 ? (darkMode ? "#6366f1" : "#4f46e5") : (darkMode ? "#334155" : "#cbd5e1")} 
                    strokeWidth={i % 6 === 0 ? 2 : 1} 
                  />
                );
              })}

              {/* Major Hour Labels */}
              <text x={center} y={center - radius - 30} textAnchor="middle" fontSize="10" fontWeight="bold" fill={darkMode ? "#64748b" : "#94a3b8"}>00:00</text>
              <text x={center + radius + 30} y={center + 4} textAnchor="start" fontSize="10" fontWeight="bold" fill={darkMode ? "#64748b" : "#94a3b8"}>06:00</text>
              <text x={center} y={center + radius + 38} textAnchor="middle" fontSize="10" fontWeight="bold" fill={darkMode ? "#64748b" : "#94a3b8"}>12:00</text>
              <text x={center - radius - 30} y={center + 4} textAnchor="end" fontSize="10" fontWeight="bold" fill={darkMode ? "#64748b" : "#94a3b8"}>18:00</text>

              {/* Session Arcs */}
              {sessions.map((session, idx) => {
                const startAngle = timeToAngle(session.startTime);
                const endAngle = timeToAngle(session.endTime);
                // Ensure endAngle is greater than startAngle for the path
                const effectiveEnd = endAngle < startAngle ? endAngle + 360 : endAngle;

                return (
                  <path
                    key={session.id}
                    d={describeArc(startAngle, effectiveEnd)}
                    fill="none"
                    stroke="#6366f1"
                    strokeWidth="24"
                    strokeLinecap="round"
                    className="transition-all hover:stroke-indigo-400 cursor-pointer"
                  >
                    <title>{session.taskTitle}: {formatTime(session.startTime)} - {formatTime(session.endTime)}</title>
                  </path>
                );
              })}
            </svg>

            <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
               <Clock size={32} className={darkMode ? 'text-slate-800' : 'text-slate-100'} />
            </div>
          </div>
        </div>

        {/* Legend/List Section */}
        <div className="flex-1 flex flex-col">
          <div className="p-6 border-b flex justify-between items-center bg-white/5">
            <div className="flex items-center gap-2">
              <Calendar size={16} className="text-indigo-500" />
              <h3 className={`text-xs font-black uppercase tracking-widest ${darkMode ? 'text-slate-200' : 'text-slate-800'}`}>Session Log</h3>
            </div>
            <button onClick={onClose} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full transition-colors">
              <X size={18} />
            </button>
          </div>

          <div className="flex-1 overflow-y-auto p-4 space-y-2">
            {sortedSessions.length > 0 ? (
              sortedSessions.map((session) => (
                <div 
                  key={session.id} 
                  className={`p-3 rounded-xl border flex items-center justify-between transition-all hover:scale-[1.01] ${darkMode ? 'bg-slate-800/50 border-slate-800 hover:bg-slate-800' : 'bg-slate-50 border-slate-100 hover:bg-white'}`}
                >
                  <div className="flex flex-col gap-0.5">
                    <span className={`text-[11px] font-bold ${darkMode ? 'text-slate-100' : 'text-slate-800'}`}>{session.taskTitle}</span>
                    <span className="text-[10px] font-medium text-slate-500">{formatTime(session.startTime)} — {formatTime(session.endTime)}</span>
                  </div>
                  <div className="bg-indigo-500/10 px-2.5 py-1 rounded-lg border border-indigo-500/20">
                    <span className="text-[10px] font-black text-indigo-500">{formatDuration(session.endTime - session.startTime)}</span>
                  </div>
                </div>
              ))
            ) : (
              <div className="h-full flex flex-col items-center justify-center opacity-30 py-12">
                <Clock size={32} className="mb-2" />
                <p className="text-[10px] font-black uppercase tracking-widest">No focus data logged today</p>
              </div>
            )}
          </div>

          <div className={`p-4 text-center ${darkMode ? 'bg-slate-950/50' : 'bg-slate-50'}`}>
            <p className="text-[9px] font-bold uppercase tracking-widest text-slate-500">
              Visualizing the last {sessions.length} sessions
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

