                    className={`bg-transparent text-[10px] font-black uppercase tracking-tighter outline-none cursor-pointer ${darkMode ? 'text-slate-400' : 'text-slate-500'}`}
                  >
                    <option value="newest" className={darkMode ? 'bg-slate-900' : ''}>Newest</option>
                    <option value="oldest" className={darkMode ? 'bg-slate-900' : ''}>Oldest</option>
                    <option value="progress" className={darkMode ? 'bg-slate-900' : ''}>Progress</option>
                  </select>
                </div>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-4 gap-3 items-start">
              {filteredAndSortedTasks.length > 0 ? (
                filteredAndSortedTasks.map(task => (
                  <TaskCard 
                    key={task.id} 
                    task={task} 
                    onUpdate={updateTask}
                    onDelete={deleteTask}
                    onStartTimer={(taskId, subtaskTitle) => setActiveTimer({ taskId, subtaskTitle })}
                    darkMode={darkMode}
                  />
                ))
              ) : (
                <div className={`col-span-full py-20 flex flex-col items-center justify-center rounded-2xl border border-dashed shadow-sm transition-colors ${darkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200'}`}>
                  <Target size={24} strokeWidth={1} className={`mb-3 ${darkMode ? 'text-slate-800' : 'text-slate-200'}`} />
                  <p className={`text-[10px] font-black uppercase tracking-[0.2em] ${darkMode ? 'text-slate-600' : 'text-slate-400'}`}>Pipeline Empty</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </main>

      {activeTimer && (
        <TimerOverlay 
          subtaskTitle={activeTimer.subtaskTitle}
          darkMode={darkMode}
          onClose={() => setActiveTimer(null)}
          onComplete={recordTime}
        />
      )}

      {isAnalysisOpen && (
        <AnalysisModal 
          sessions={allSessions}
          onClose={() => setIsAnalysisOpen(false)}
          darkMode={darkMode}
        />
      )}

      {showAddModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/20 dark:bg-black/40 backdrop-blur-[2px] animate-in fade-in duration-200">
          <div className={`w-full max-w-sm rounded-2xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200 border transition-colors ${darkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-100'}`}>
            <div className="p-6">
              <h2 className={`text-sm font-black uppercase tracking-wider mb-5 ${darkMode ? 'text-slate-200' : 'text-slate-800'}`}>Create Task</h2>
              <form onSubmit={addTask} className="space-y-4">
                <div className="space-y-1">
                  <label className={`text-[10px] font-black uppercase tracking-widest ml-1 ${darkMode ? 'text-slate-500' : 'text-slate-400'}`}>Title</label>
                  <input
                    autoFocus required type="text"
                    value={newTask.title}
                    onChange={(e) => setNewTask({ ...newTask, title: e.target.value })}
                    className={`w-full px-3 py-2 border rounded-xl text-xs font-semibold outline-none focus:ring-1 focus:ring-indigo-500 transition-colors ${darkMode ? 'bg-slate-800 border-slate-700 text-slate-100' : 'bg-slate-50 border-slate-100 text-slate-900'}`}
                    placeholder="Enter goal name..."
                  />
                </div>
                <div className="flex gap-2 pt-3">
                  <button type="button" onClick={() => setShowAddModal(false)} className={`flex-1 py-2 text-[10px] font-black uppercase tracking-widest ${darkMode ? 'text-slate-50 hover:text-slate-400' : 'text-slate-400 hover:text-slate-500'}`}>Cancel</button>
                  <button type="submit" className="flex-1 py-2 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg shadow-indigo-100 dark:shadow-none">Create</button>
                </div>
              </form>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { X, Play, Pause, Timer as TimerIcon } from 'lucide-react';

interface TimerOverlayProps {
  subtaskTitle: string;
  onClose: () => void;
  onComplete: (elapsedSeconds: number, startTime: number, endTime: number) => void;
  darkMode: boolean;
}

const MOTIVATIONAL_QUOTES = ["Bit by Bit", "Stay Focused", "One Step Closer", "Keep Pushing"];

const TimerOverlay: React.FC<TimerOverlayProps> = ({ subtaskTitle, onClose, onComplete, darkMode }) => {
  const [duration, setDuration] = useState<number>(25); 
  const [timeLeft, setTimeLeft] = useState<number>(0);
  const [isActive, setIsActive] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [isStarted, setIsStarted] = useState(false);
  const [elapsed, setElapsed] = useState(0);
  const [quoteIndex, setQuoteIndex] = useState(0);

  const startTimeRef = useRef<number | null>(null);
  const timerRef = useRef<number | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);

  const size = 320;
  const strokeWidth = 8;
  const radius = (size - strokeWidth) / 2;
  const circumference = radius * 2 * Math.PI;

  const playRingSound = () => {
    try {
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      }
      const ctx = audioContextRef.current;
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(880, ctx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(440, ctx.currentTime + 0.5);
      gain.gain.setValueAtTime(0, ctx.currentTime);
      gain.gain.linearRampToValueAtTime(0.2, ctx.currentTime + 0.1);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 1.5);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start();
      osc.stop(ctx.currentTime + 1.5);
    } catch (e) { console.warn(e); }
  };

  const startTimer = () => {
    startTimeRef.current = Date.now();
    const totalSeconds = duration * 60;
    setTimeLeft(totalSeconds);
    setIsStarted(true);
    setIsActive(true);
    setIsPaused(false);
    setQuoteIndex(Math.floor(Math.random() * MOTIVATIONAL_QUOTES.length));
  };

  const togglePause = () => setIsPaused(!isPaused);

  const finishTimer = () => {
    if (timerRef.current) clearInterval(timerRef.current);
    const endTime = Date.now();
    onComplete(elapsed, startTimeRef.current || Date.now(), endTime);
    onClose();
  };

  useEffect(() => {
    if (isActive && !isPaused && timeLeft > 0) {
      timerRef.current = window.setInterval(() => {
        setTimeLeft((prev) => prev - 1);
        setElapsed((prev) => prev + 1);
      }, 1000);
    } else if (timerRef.current) {
      clearInterval(timerRef.current);
    }
    if (timeLeft === 0 && isStarted && isActive) {
      setIsActive(false);
      playRingSound();
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [isActive, isPaused, timeLeft]);

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  const progressOffset = isStarted 
    ? (timeLeft / (duration * 60)) * circumference 
    : circumference;

  if (!isStarted) {
    return (
      <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-md animate-in fade-in duration-300">
        <div className={`w-full max-w-sm rounded-3xl p-8 shadow-2xl ${darkMode ? 'bg-slate-900 text-white' : 'bg-white text-slate-900'}`}>
          <div className="flex justify-between items-center mb-6">
            <h2 className="text-xl font-light uppercase tracking-widest">Set Focus Timer</h2>
            <button onClick={onClose} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full">
              <X size={20} />
            </button>
          </div>
          <p className="text-xs font-medium text-slate-400 mb-8 uppercase tracking-widest">Target: {subtaskTitle}</p>
          <div className="flex flex-col items-center gap-6">
            <div className="text-6xl font-light tracking-tighter text-indigo-500">{duration}m</div>
            <input type="range" min="1" max="120" value={duration} onChange={(e) => setDuration(parseInt(e.target.value))} className="w-full h-1.5 bg-slate-200 dark:bg-slate-800 rounded-lg appearance-none cursor-pointer accent-indigo-500" />
            <button onClick={startTimer} className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 text-white rounded-2xl font-medium uppercase tracking-widest shadow-xl shadow-indigo-500/20 transition-all flex items-center justify-center gap-2"><Play size={18} /> Start Focus</button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className={`fixed inset-0 z-[100] flex flex-col items-center justify-center transition-colors duration-700 ${darkMode ? 'bg-slate-950 text-white' : 'bg-indigo-600 text-white'} animate-in zoom-in-110 duration-500`}>
      <div className="absolute top-10 left-10 flex items-center gap-3">
        <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${darkMode ? 'bg-indigo-500/20' : 'bg-white/20'}`}><TimerIcon size={24} /></div>
        <div>
          <p className="text-[10px] font-black uppercase tracking-widest opacity-50">Current Focus</p>
          <h3 className="text-sm font-bold truncate max-w-[200px]">{subtaskTitle}</h3>
        </div>
      </div>

      <button 
        onClick={onClose}
        className="absolute top-10 right-10 p-3 hover:bg-white/10 rounded-full transition-colors"
      >
        <X size={24} />
      </button>

      <div className="relative flex items-center justify-center" style={{ width: size, height: size }}>
        <svg width={size} height={size} className="transform -rotate-90">
          <circle
            cx={size / 2}
            cy={size / 2}
            r={radius}
            stroke="currentColor"
            strokeWidth={strokeWidth}
            fill="transparent"
            className="opacity-10"
          />
          <circle
            cx={size / 2}
            cy={size / 2}
            r={radius}
            stroke="white"
            strokeWidth={strokeWidth}
            strokeDasharray={circumference}
            strokeDashoffset={circumference - progressOffset}
            strokeLinecap="round"
            fill="transparent"
            style={{ transition: 'stroke-dashoffset 1s linear' }}
          />
        </svg>
        <div className="absolute flex flex-col items-center">
          <span className="text-7xl font-light tracking-tighter mb-2">
            {formatTime(timeLeft)}
          </span>
          <span className="text-[10px] font-black uppercase tracking-[0.3em] opacity-40">
            {MOTIVATIONAL_QUOTES[quoteIndex]}
          </span>
        </div>
      </div>

      <div className="mt-12 flex items-center gap-4">
        <button 
          onClick={togglePause}
          className={`w-16 h-16 rounded-full flex items-center justify-center transition-all ${darkMode ? 'bg-slate-900 hover:bg-slate-800' : 'bg-white/10 hover:bg-white/20'}`}
        >
          {isPaused ? <Play size={24} /> : <Pause size={24} />}
        </button>
        <button 
          onClick={finishTimer}
          className="px-8 py-4 bg-white text-indigo-600 rounded-2xl font-black uppercase tracking-widest text-[11px] hover:scale-105 transition-transform shadow-2xl"
        >
          Finish Session
        </button>
      </div>

      {timeLeft === 0 && (
        <div className="mt-8 animate-bounce text-xs font-black uppercase tracking-widest opacity-80">
          Time's up! Great work.
        </div>
      )}
    </div>
  );
};

export default TimerOverlay;
